INSERT INTO AD_CtxHelpMsg_Trl (AD_CtxHelpMsg_ID, AD_Language, AD_CtxHelpMsg_Trl_UU, AD_Client_ID, AD_Org_ID, Created, CreatedBy, Updated, UpdatedBy, IsActive, IsTranslated, MsgText)
SELECT toRecordId('AD_CtxHelpMsg', '498dcddc-a565-5776-bee2-9ad650a68660'), r.AD_Language, generate_uuid(), 0, 0, now(), 100, now(), 100, 'Y', 'N', (SELECT x.dict || COALESCE(string_agg(b.html, '' ORDER BY b.k) FILTER (WHERE b.k <= x.j), '') || COALESCE(max(b.more) FILTER (WHERE b.k = x.j + 1), '') FROM (SELECT y.dict, y.l, COALESCE((SELECT min(c.k) FROM (SELECT k, sum(length(html)) OVER (ORDER BY k) AS cum, nextlen FROM blk WHERE lang = y.l) c WHERE length(y.dict) + c.cum + c.nextlen > y.lim) - 1, (SELECT max(k) FROM blk WHERE lang = y.l)) AS j FROM (SELECT '<p><strong>' || r.Name || '</strong></p>' || COALESCE('<p><em>' || NULLIF(r.Description, '') || '</em></p>', '') || COALESCE('<p>' || NULLIF(r.Help, '') || '</p>', '') || '<hr>' AS dict, CASE WHEN EXISTS (SELECT 1 FROM blk WHERE lang = r.AD_Language) THEN r.AD_Language ELSE 'en' END AS l, (SELECT c.FieldLength FROM AD_Column c JOIN AD_Table tb ON tb.AD_Table_ID=c.AD_Table_ID WHERE tb.TableName='AD_CtxHelpMsg_Trl' AND c.ColumnName='MsgText') AS lim) y) x JOIN blk b ON b.lang = x.l GROUP BY x.dict, x.j)
FROM AD_Tab_Trl r WHERE r.AD_Tab_ID=186
ON CONFLICT (AD_CtxHelpMsg_ID, AD_Language) DO UPDATE SET MsgText=EXCLUDED.MsgText, Updated=now() WHERE AD_CtxHelpMsg_Trl.MsgText IS DISTINCT FROM EXCLUDED.MsgText;
UPDATE AD_Tab SET AD_CtxHelp_ID=toRecordId('AD_CtxHelp', '2296041b-0c8b-550a-abab-7b73e9c6df3b'), Updated=now() WHERE AD_Tab_ID=186 AND AD_CtxHelp_ID IS NULL;

-- tab 257 Shipment: DV169 + UG2 (twin help 1000001)
INSERT INTO AD_CtxHelp (AD_CtxHelp_ID, AD_CtxHelp_UU, AD_Client_ID, AD_Org_ID, Created, CreatedBy, Updated, UpdatedBy, IsActive, CtxType, Name, Description)
SELECT COALESCE((SELECT AD_CtxHelp_ID FROM AD_CtxHelp WHERE AD_CtxHelp_UU='88553452-b4a3-594f-936c-51f8d4303780'), nextidfunc((SELECT AD_Sequence_ID FROM AD_Sequence WHERE Name='AD_CtxHelp' AND IsTableID='Y')::integer, 'N')), '88553452-b4a3-594f-936c-51f8d4303780', 0, 0, now(), 100, now(), 100, 'Y', 'T', 'Shipment (Customer) + 2 · Shipment', 'https://red1oon.github.io/BIMCompiler/ERPUserGuide/#2-shipment'
ON CONFLICT (AD_CtxHelp_UU) DO UPDATE SET Name=EXCLUDED.Name, Description=EXCLUDED.Description, Updated=now() WHERE (AD_CtxHelp.Name, AD_CtxHelp.Description) IS DISTINCT FROM (EXCLUDED.Name, EXCLUDED.Description);
WITH blk(lang, k, html, more, nextlen) AS (VALUES
  ('en', 1, '<p><strong>Shipment (Customer)</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Shipment (Customer) …</a></p>', 121),
  ('en', 2, '<p><b>Before you start.</b> These must exist first: <b>Business Partner</b>, Partner Location (<b>Business Partner</b>).</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Shipment (Customer) …</a></p>', 121),
  ('en', 3, '<p><b>Do it.</b> Fill <b>Shipment</b>, then <b>Shipment Line</b>, <b>Packages</b>; then the Document Action <b>Complete</b>.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Shipment (Customer) …</a></p>', 121),
  ('en', 4, '<p><b>What Complete does.</b></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Shipment (Customer) …</a></p>', 121),
  ('en', 5, '<ul><li>Pick/QA Confirmation: Yes: creates a pick/QA confirmation document with one line per shipment line</li><li>Ship/Receipt Confirmation: Yes: creates a ship/receipt confirmation (after the pick/QA one when both are on)</li><li>Stays In Progress while a non-customer confirmation is unprocessed</li><li>Movement Type Customer Shipment, Vendor Returns: takes the line quantity out of the locator''s on-hand stock (stocked products)</li><li>Movement Type Customer Returns, Vendor Receipts: adds the line quantity to the locator''s on-hand stock (stocked products)</li><li>Reduces the product''s reserved stock for the order line''s warehouse ✓</li><li>Raises order line delivered qty on shipment (C-), lowers it on customer return (C+) ✓</li><li>Offers Close as the next document action</li></ul>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Shipment (Customer) …</a></p>', 121),
  ('en', 6, '<p><b>When it refuses</b>, legacy says: “Either Order or RMA can be process on this document.”; “Period Closed”; “Back-Date transaction not allowed”; “No Document Lines found”; “Attribute Set Mandatory (Line No #… , Product=… )”; “Open: Ship/Receipt Confirmation”; “Insufficient Stock Coverage. A shipment should not be allowed if there is insufficient stock before the shipment’s movement date.”; “More than line qty on attribute tab for line …”; “Cannot correct Inventory OnHand (MA) [… ] - …”; and 9 more in MInOut.java.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Shipment (Customer) …</a></p>', 121),
  ('en', 7, '<p><i>Read from iDempiere''s MInOut.java and the dictionary. ✓ = seen in a legacy run of 2026-11-23.</i></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Shipment (Customer) …</a></p>', 114),
  ('en', 8, '<p><strong>2 · Shipment</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#2-shipment" target="_blank">2 · Shipment …</a></p>', 114),
  ('en', 9, '<p>The <b>Shipment</b> (<code><b>M_InOut</b></code>) that Complete generated is a real window of its own (⌂ → Inventory → Shipment) — open it to see the same document from the warehouse side. On-hand for every shipped product drops immediately; the shipment also carries its own GL leg (Cost of Goods Sold against Inventory), not just a paper movement.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#2-shipment" target="_blank">2 · Shipment …</a></p>', 0),
  ('de_DE', 1, '<p><strong>2 · Lieferung</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#2-shipment" target="_blank">2 · Lieferung …</a></p>', 115),
  ('de_DE', 2, '<p>Die <b><b>Lieferung (Kunde)</b></b> (<code>M_InOut</code>), die Fertigstellen erzeugt hat, ist ein eigenes Fenster (⌂ → Lager → Lieferung) — öffnen Sie es, um denselben Beleg von der Lagerseite zu sehen. Der Bestand jedes gelieferten Produkts sinkt sofort; die Lieferung hat außerdem eine eigene Buchung (Wareneinsatz gegen Lagerbestand), nicht nur eine Papierbewegung.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#2-shipment" target="_blank">2 · Lieferung …</a></p>', 121),
  ('de_DE', 3, '<p><strong>Shipment (Customer)</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Shipment (Customer) …</a></p>', 121),
  ('de_DE', 4, '<p><b>Before you start.</b> These must exist first: <b>Business Partner</b>, Partner Location (<b>Business Partner</b>).</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Shipment (Customer) …</a></p>', 121),
  ('de_DE', 5, '<p><b>Do it.</b> Fill <b>Shipment</b>, then <b>Shipment Line</b>, <b>Packages</b>; then the Document Action <b>Complete</b>.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Shipment (Customer) …</a></p>', 121),
  ('de_DE', 6, '<p><b>What Complete does.</b></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Shipment (Customer) …</a></p>', 121),
