  ('zh_CN', 1, '<p><strong>2 · 出货</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#2-shipment" target="_blank">2 · 出货 …</a></p>', 108),
  ('zh_CN', 2, '<p>完成时生成的<b><b>物料出货(客户/公司)</b></b>（<code>M_InOut</code>）是一个独立的窗口（⌂ → 库存 → 出货）——打开它，从仓库一侧看同一张单据。每个已出货产品的现有库存立即减少；出货单还带有自己的总账分录（销货成本对库存），而不只是纸面上的移动。</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#2-shipment" target="_blank">2 · 出货 …</a></p>', 121),
