INSERT INTO AD_CtxHelpMsg_Trl (AD_CtxHelpMsg_ID, AD_Language, AD_CtxHelpMsg_Trl_UU, AD_Client_ID, AD_Org_ID, Created, CreatedBy, Updated, UpdatedBy, IsActive, IsTranslated, MsgText)
SELECT toRecordId('AD_CtxHelpMsg', 'd2297abb-346f-57dd-ace4-141a5691feca'), r.AD_Language, generate_uuid(), 0, 0, now(), 100, now(), 100, 'Y', 'N', (SELECT x.dict || COALESCE(string_agg(b.html, '' ORDER BY b.k) FILTER (WHERE b.k <= x.j), '') || COALESCE(max(b.more) FILTER (WHERE b.k = x.j + 1), '') FROM (SELECT y.dict, y.l, COALESCE((SELECT min(c.k) FROM (SELECT k, sum(length(html)) OVER (ORDER BY k) AS cum, nextlen FROM blk WHERE lang = y.l) c WHERE length(y.dict) + c.cum + c.nextlen > y.lim) - 1, (SELECT max(k) FROM blk WHERE lang = y.l)) AS j FROM (SELECT '<p><strong>' || r.Name || '</strong></p>' || COALESCE('<p><em>' || NULLIF(r.Description, '') || '</em></p>', '') || COALESCE('<p>' || NULLIF(r.Help, '') || '</p>', '') || '<hr>' AS dict, CASE WHEN EXISTS (SELECT 1 FROM blk WHERE lang = r.AD_Language) THEN r.AD_Language ELSE 'en' END AS l, (SELECT c.FieldLength FROM AD_Column c JOIN AD_Table tb ON tb.AD_Table_ID=c.AD_Table_ID WHERE tb.TableName='AD_CtxHelpMsg_Trl' AND c.ColumnName='MsgText') AS lim) y) x JOIN blk b ON b.lang = x.l GROUP BY x.dict, x.j)
FROM AD_Tab_Trl r WHERE r.AD_Tab_ID=257
ON CONFLICT (AD_CtxHelpMsg_ID, AD_Language) DO UPDATE SET MsgText=EXCLUDED.MsgText, Updated=now() WHERE AD_CtxHelpMsg_Trl.MsgText IS DISTINCT FROM EXCLUDED.MsgText;
UPDATE AD_Tab SET AD_CtxHelp_ID=toRecordId('AD_CtxHelp', '88553452-b4a3-594f-936c-51f8d4303780'), Updated=now() WHERE AD_Tab_ID=257 AND AD_CtxHelp_ID IS NULL;

