  ('zh_CN', 7, '<ul><li>Payment Rule On Credit, Direct Debit: creates the invoice payment schedule</li><li>Payment Rule Cash: creates and completes a cash payment for the invoice total</li><li>Adds the invoiced quantity to the sales order line ✓</li><li>Prepay Order: allocates completed unallocated prepayments of the order to the invoice</li><li>Adds invoice total to partner open balance (cash rule non-POS excepted) ✓</li><li>Adds invoice total to partner credit used ✓</li><li>Offers Close as the next document action</li></ul>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Sales Invoice and Credit/Debit Note …</a></p>', 137),
