INSERT INTO AD_CtxHelpMsg_Trl (AD_CtxHelpMsg_ID, AD_Language, AD_CtxHelpMsg_Trl_UU, AD_Client_ID, AD_Org_ID, Created, CreatedBy, Updated, UpdatedBy, IsActive, IsTranslated, MsgText)
SELECT toRecordId('AD_CtxHelpMsg', '07e57b25-c992-597a-b4e2-ce816573562f'), r.AD_Language, generate_uuid(), 0, 0, now(), 100, now(), 100, 'Y', 'N', (SELECT x.dict || COALESCE(string_agg(b.html, '' ORDER BY b.k) FILTER (WHERE b.k <= x.j), '') || COALESCE(max(b.more) FILTER (WHERE b.k = x.j + 1), '') FROM (SELECT y.dict, y.l, COALESCE((SELECT min(c.k) FROM (SELECT k, sum(length(html)) OVER (ORDER BY k) AS cum, nextlen FROM blk WHERE lang = y.l) c WHERE length(y.dict) + c.cum + c.nextlen > y.lim) - 1, (SELECT max(k) FROM blk WHERE lang = y.l)) AS j FROM (SELECT '<p><strong>' || r.Name || '</strong></p>' || COALESCE('<p><em>' || NULLIF(r.Description, '') || '</em></p>', '') || COALESCE('<p>' || NULLIF(r.Help, '') || '</p>', '') || '<hr>' AS dict, CASE WHEN EXISTS (SELECT 1 FROM blk WHERE lang = r.AD_Language) THEN r.AD_Language ELSE 'en' END AS l, (SELECT c.FieldLength FROM AD_Column c JOIN AD_Table tb ON tb.AD_Table_ID=c.AD_Table_ID WHERE tb.TableName='AD_CtxHelpMsg_Trl' AND c.ColumnName='MsgText') AS lim) y) x JOIN blk b ON b.lang = x.l GROUP BY x.dict, x.j)
FROM AD_Tab_Trl r WHERE r.AD_Tab_ID=263
ON CONFLICT (AD_CtxHelpMsg_ID, AD_Language) DO UPDATE SET MsgText=EXCLUDED.MsgText, Updated=now() WHERE AD_CtxHelpMsg_Trl.MsgText IS DISTINCT FROM EXCLUDED.MsgText;
UPDATE AD_Tab SET AD_CtxHelp_ID=toRecordId('AD_CtxHelp', '5839dce2-b7ee-59e4-beed-f7c1271e6fb2'), Updated=now() WHERE AD_Tab_ID=263 AND AD_CtxHelp_ID IS NULL;

-- tab 330 Payment: DV195 + UG4 (twin help 1000003)
INSERT INTO AD_CtxHelp (AD_CtxHelp_ID, AD_CtxHelp_UU, AD_Client_ID, AD_Org_ID, Created, CreatedBy, Updated, UpdatedBy, IsActive, CtxType, Name, Description)
SELECT COALESCE((SELECT AD_CtxHelp_ID FROM AD_CtxHelp WHERE AD_CtxHelp_UU='58ae1a39-20e8-5ab9-9089-6877e251d3e2'), nextidfunc((SELECT AD_Sequence_ID FROM AD_Sequence WHERE Name='AD_CtxHelp' AND IsTableID='Y')::integer, 'N')), '58ae1a39-20e8-5ab9-9089-6877e251d3e2', 0, 0, now(), 100, now(), 100, 'Y', 'T', 'Payment and Receipt + 4 · Receipt & Allocation', 'https://red1oon.github.io/BIMCompiler/ERPUserGuide/#4-receipt-allocation'
ON CONFLICT (AD_CtxHelp_UU) DO UPDATE SET Name=EXCLUDED.Name, Description=EXCLUDED.Description, Updated=now() WHERE (AD_CtxHelp.Name, AD_CtxHelp.Description) IS DISTINCT FROM (EXCLUDED.Name, EXCLUDED.Description);
WITH blk(lang, k, html, more, nextlen) AS (VALUES
  ('en', 1, '<p><strong>Payment and Receipt</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Payment and Receipt …</a></p>', 121),
  ('en', 2, '<p><b>Before you start.</b> These must exist first: <b>Document Type</b>, <b>Business Partner</b>, <b>Currency</b>.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Payment and Receipt …</a></p>', 121),
  ('en', 3, '<p><b>Do it.</b> Fill <b>Payment</b>, then <b>Allocate</b>, <b>Allocations</b>; then the Document Action <b>Complete</b>.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Payment and Receipt …</a></p>', 121),
  ('en', 4, '<p><b>What Complete does.</b></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Payment and Receipt …</a></p>', 121),
  ('en', 5, '<ul><li>Order Document Status Waiting Payment: completes the waiting-payment order so its invoice and shipment are created</li><li>with Invoice: creates and completes an allocation of the payment to its invoice</li><li>without Invoice: creates and completes an allocation from the payment allocate lines</li><li>Receipt: Yes: subtracts payment amount from partner open balance (unallocated prepayment)</li><li>Receipt: No: adds payment amount to partner open balance (unallocated prepayment)</li><li>Offers Close as the next document action</li></ul>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Payment and Receipt …</a></p>', 121),
  ('en', 6, '<p><b>When it refuses</b>, legacy says: “Could not delete draft generated payment selection lines”; “Period Closed”; “Online Payment Failed”; “Payment process failed”; “* Not found * Invoice”; “Payment Document Type and Invoice type (AP/AR) inconsistent.”; “Payment Allocate must not exists if the payment header has charge/invoice/order.”; “Payment Amount must be equal to the sum of Allocate amounts.”; “NoCashBook”; “Could not save Cash Journal Line”.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Payment and Receipt …</a></p>', 121),
  ('en', 7, '<p><i>Read from iDempiere''s MPayment.java and the dictionary. ✓ = seen in a legacy run of 2026-11-23.</i></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Payment and Receipt …</a></p>', 140),
  ('en', 8, '<p><strong>4 · Receipt &amp; Allocation</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#4-receipt-allocation" target="_blank">4 · Receipt &amp; Allocation …</a></p>', 140),
  ('en', 9, '<p>Record the customer''s <b><b>Payment</b></b> (⌂ → Sales → Payment) against the invoice, then run <b><b>Allocation</b></b> to match payment to invoice. A real allocation is rarely an exact match — it can carry a discount, a write-off, and (because tax rides the discounted portion too) a VAT correction, all in the same posting.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#4-receipt-allocation" target="_blank">4 · Receipt &amp; Allocation …</a></p>', 0),
  ('de_DE', 1, '<p><strong>4 · Zahlungseingang und Zuordnung</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#4-receipt-allocation" target="_blank">4 · Zahlungseingang und Zuordnung …</a></p>', 145),
  ('de_DE', 2, '<p>Erfassen Sie die <b><b>Zahlung</b></b> des Kunden (⌂ → Vertrieb → Zahlung) zur Rechnung und führen Sie dann die <b>Zuordnung</b> aus, um Zahlung und Rechnung abzugleichen. Eine echte Zuordnung passt selten genau — sie kann einen Skonto, eine Abschreibung und (weil die Steuer auch auf den Skontoanteil entfällt) eine Umsatzsteuerkorrektur enthalten, alles in derselben Buchung.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#4-receipt-allocation" target="_blank">4 · Zahlungseingang und Zuordnung …</a></p>', 121),
  ('de_DE', 3, '<p><strong>Payment and Receipt</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Payment and Receipt …</a></p>', 121),
  ('de_DE', 4, '<p><b>Before you start.</b> These must exist first: <b>Document Type</b>, <b>Business Partner</b>, <b>Currency</b>.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Payment and Receipt …</a></p>', 121),
  ('de_DE', 5, '<p><b>Do it.</b> Fill <b>Payment</b>, then <b>Allocate</b>, <b>Allocations</b>; then the Document Action <b>Complete</b>.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Payment and Receipt …</a></p>', 121),
  ('de_DE', 6, '<p><b>What Complete does.</b></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Payment and Receipt …</a></p>', 121),
  ('de_DE', 7, '<ul><li>Order Document Status Waiting Payment: completes the waiting-payment order so its invoice and shipment are created</li><li>with Invoice: creates and completes an allocation of the payment to its invoice</li><li>without Invoice: creates and completes an allocation from the payment allocate lines</li><li>Receipt: Yes: subtracts payment amount from partner open balance (unallocated prepayment)</li><li>Receipt: No: adds payment amount to partner open balance (unallocated prepayment)</li><li>Offers Close as the next document action</li></ul>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Payment and Receipt …</a></p>', 121),
  ('de_DE', 8, '<p><b>When it refuses</b>, legacy says: “Could not delete draft generated payment selection lines”; “Period Closed”; “Online Payment Failed”; “Payment process failed”; “* Not found * Invoice”; “Payment Document Type and Invoice type (AP/AR) inconsistent.”; “Payment Allocate must not exists if the payment header has charge/invoice/order.”; “Payment Amount must be equal to the sum of Allocate amounts.”; “NoCashBook”; “Could not save Cash Journal Line”.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Payment and Receipt …</a></p>', 121),
  ('de_DE', 9, '<p><i>Read from iDempiere''s MPayment.java and the dictionary. ✓ = seen in a legacy run of 2026-11-23.</i></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Payment and Receipt …</a></p>', 0),
  ('zh_CN', 1, '<p><strong>4 · 收款与分配</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#4-receipt-allocation" target="_blank">4 · 收款与分配 …</a></p>', 121),
  ('zh_CN', 2, '<p>针对发票记录客户的<b><b>付款</b></b>（⌂ → 销售 → 付款），然后运行<b>分配</b>，把付款和发票对上。真实的分配很少正好相等——它可以带折扣、核销，以及（因为税也跟着折扣部分走）增值税调整，全部在同一笔记账里。</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#4-receipt-allocation" target="_blank">4 · 收款与分配 …</a></p>', 121),
  ('zh_CN', 3, '<p><strong>Payment and Receipt</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Payment and Receipt …</a></p>', 121),
  ('zh_CN', 4, '<p><b>Before you start.</b> These must exist first: <b>Document Type</b>, <b>Business Partner</b>, <b>Currency</b>.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Payment and Receipt …</a></p>', 121),
  ('zh_CN', 5, '<p><b>Do it.</b> Fill <b>Payment</b>, then <b>Allocate</b>, <b>Allocations</b>; then the Document Action <b>Complete</b>.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Payment and Receipt …</a></p>', 121),
  ('zh_CN', 6, '<p><b>What Complete does.</b></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Payment and Receipt …</a></p>', 121),
  ('zh_CN', 7, '<ul><li>Order Document Status Waiting Payment: completes the waiting-payment order so its invoice and shipment are created</li><li>with Invoice: creates and completes an allocation of the payment to its invoice</li><li>without Invoice: creates and completes an allocation from the payment allocate lines</li><li>Receipt: Yes: subtracts payment amount from partner open balance (unallocated prepayment)</li><li>Receipt: No: adds payment amount to partner open balance (unallocated prepayment)</li><li>Offers Close as the next document action</li></ul>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Payment and Receipt …</a></p>', 121),
  ('zh_CN', 8, '<p><b>When it refuses</b>, legacy says: “Could not delete draft generated payment selection lines”; “Period Closed”; “Online Payment Failed”; “Payment process failed”; “* Not found * Invoice”; “Payment Document Type and Invoice type (AP/AR) inconsistent.”; “Payment Allocate must not exists if the payment header has charge/invoice/order.”; “Payment Amount must be equal to the sum of Allocate amounts.”; “NoCashBook”; “Could not save Cash Journal Line”.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Payment and Receipt …</a></p>', 121),
