  ('zh_CN', 9, '<p><i>Read from iDempiere''s MPayment.java and the dictionary. ✓ = seen in a legacy run of 2026-11-23.</i></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Payment and Receipt …</a></p>', 0))
INSERT INTO AD_CtxHelpMsg_Trl (AD_CtxHelpMsg_ID, AD_Language, AD_CtxHelpMsg_Trl_UU, AD_Client_ID, AD_Org_ID, Created, CreatedBy, Updated, UpdatedBy, IsActive, IsTranslated, MsgText)
SELECT toRecordId('AD_CtxHelpMsg', '4cf1f1b2-4333-5e98-88c0-ce70292497c6'), r.AD_Language, generate_uuid(), 0, 0, now(), 100, now(), 100, 'Y', 'N', (SELECT x.dict || COALESCE(string_agg(b.html, '' ORDER BY b.k) FILTER (WHERE b.k <= x.j), '') || COALESCE(max(b.more) FILTER (WHERE b.k = x.j + 1), '') FROM (SELECT y.dict, y.l, COALESCE((SELECT min(c.k) FROM (SELECT k, sum(length(html)) OVER (ORDER BY k) AS cum, nextlen FROM blk WHERE lang = y.l) c WHERE length(y.dict) + c.cum + c.nextlen > y.lim) - 1, (SELECT max(k) FROM blk WHERE lang = y.l)) AS j FROM (SELECT '<p><strong>' || r.Name || '</strong></p>' || COALESCE('<p><em>' || NULLIF(r.Description, '') || '</em></p>', '') || COALESCE('<p>' || NULLIF(r.Help, '') || '</p>', '') || '<hr>' AS dict, CASE WHEN EXISTS (SELECT 1 FROM blk WHERE lang = r.AD_Language) THEN r.AD_Language ELSE 'en' END AS l, (SELECT c.FieldLength FROM AD_Column c JOIN AD_Table tb ON tb.AD_Table_ID=c.AD_Table_ID WHERE tb.TableName='AD_CtxHelpMsg_Trl' AND c.ColumnName='MsgText') AS lim) y) x JOIN blk b ON b.lang = x.l GROUP BY x.dict, x.j)
FROM AD_Tab_Trl r WHERE r.AD_Tab_ID=330
ON CONFLICT (AD_CtxHelpMsg_ID, AD_Language) DO UPDATE SET MsgText=EXCLUDED.MsgText, Updated=now() WHERE AD_CtxHelpMsg_Trl.MsgText IS DISTINCT FROM EXCLUDED.MsgText;
UPDATE AD_Tab SET AD_CtxHelp_ID=toRecordId('AD_CtxHelp', '58ae1a39-20e8-5ab9-9089-6877e251d3e2'), Updated=now() WHERE AD_Tab_ID=330 AND AD_CtxHelp_ID IS NULL;

-- process 53267 Replenish Report: UG5 (twin help 1000004)
INSERT INTO AD_CtxHelp (AD_CtxHelp_ID, AD_CtxHelp_UU, AD_Client_ID, AD_Org_ID, Created, CreatedBy, Updated, UpdatedBy, IsActive, CtxType, Name, Description)
SELECT COALESCE((SELECT AD_CtxHelp_ID FROM AD_CtxHelp WHERE AD_CtxHelp_UU='1f798628-92aa-5b4e-af9e-f2f7bd7716ae'), nextidfunc((SELECT AD_Sequence_ID FROM AD_Sequence WHERE Name='AD_CtxHelp' AND IsTableID='Y')::integer, 'N')), '1f798628-92aa-5b4e-af9e-f2f7bd7716ae', 0, 0, now(), 100, now(), 100, 'Y', 'P', '5 · Replenishment', 'https://red1oon.github.io/BIMCompiler/ERPUserGuide/#5-replenishment'
ON CONFLICT (AD_CtxHelp_UU) DO UPDATE SET Name=EXCLUDED.Name, Description=EXCLUDED.Description, Updated=now() WHERE (AD_CtxHelp.Name, AD_CtxHelp.Description) IS DISTINCT FROM (EXCLUDED.Name, EXCLUDED.Description);
WITH blk(lang, k, html, more, nextlen) AS (VALUES
  ('en', 1, '<p><strong>5 · Replenishment</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#5-replenishment" target="_blank">5 · Replenishment …</a></p>', 124),
  ('en', 2, '<p>The sale just dropped on-hand. Rather than reorder on every sale, <b>Replenishment</b> is the staged, reviewable action that watches on-hand against each product''s stock policy and proposes what to order — walked in detail in the POS section''s <b>§P-4</b> (the same engine, reached from a friendlier panel there; not repeated here).</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#5-replenishment" target="_blank">5 · Replenishment …</a></p>', 0),
  ('de_DE', 1, '<p><strong>5 · Nachbestellung</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#5-replenishment" target="_blank">5 · Nachbestellung …</a></p>', 125),
  ('de_DE', 2, '<p>Der Verkauf hat den Lagerbestand gerade gesenkt. Statt bei jedem Verkauf nachzubestellen, ist die <b>Nachbestellung</b> der gestufte, prüfbare Schritt, der den Bestand jedes Produkts gegen seine Lagerregel beobachtet und vorschlägt, was zu bestellen ist — ausführlich beschrieben im Abschnitt POS unter <b>§P-4</b> (dieselbe Logik, dort über ein freundlicheres Panel erreichbar; hier nicht wiederholt).</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#5-replenishment" target="_blank">5 · Nachbestellung …</a></p>', 0))
INSERT INTO AD_CtxHelpMsg (AD_CtxHelpMsg_ID, AD_CtxHelpMsg_UU, AD_CtxHelp_ID, AD_Client_ID, AD_Org_ID, Created, CreatedBy, Updated, UpdatedBy, IsActive, MsgText)
SELECT COALESCE((SELECT AD_CtxHelpMsg_ID FROM AD_CtxHelpMsg WHERE AD_CtxHelpMsg_UU='ca6f0143-c5d5-53be-9d2d-0d05ac4caf86'), nextidfunc((SELECT AD_Sequence_ID FROM AD_Sequence WHERE Name='AD_CtxHelpMsg' AND IsTableID='Y')::integer, 'N')), 'ca6f0143-c5d5-53be-9d2d-0d05ac4caf86', toRecordId('AD_CtxHelp', '1f798628-92aa-5b4e-af9e-f2f7bd7716ae'), 0, 0, now(), 100, now(), 100, 'Y', (SELECT x.dict || COALESCE(string_agg(b.html, '' ORDER BY b.k) FILTER (WHERE b.k <= x.j), '') || COALESCE(max(b.more) FILTER (WHERE b.k = x.j + 1), '') FROM (SELECT y.dict, y.l, COALESCE((SELECT min(c.k) FROM (SELECT k, sum(length(html)) OVER (ORDER BY k) AS cum, nextlen FROM blk WHERE lang = y.l) c WHERE length(y.dict) + c.cum + c.nextlen > y.lim) - 1, (SELECT max(k) FROM blk WHERE lang = y.l)) AS j FROM (SELECT '<p><strong>' || r.Name || '</strong></p>' || COALESCE('<p><em>' || NULLIF(r.Description, '') || '</em></p>', '') || COALESCE('<p>' || NULLIF(r.Help, '') || '</p>', '') || '<hr>' AS dict, 'en' AS l, (SELECT c.FieldLength FROM AD_Column c JOIN AD_Table tb ON tb.AD_Table_ID=c.AD_Table_ID WHERE tb.TableName='AD_CtxHelpMsg' AND c.ColumnName='MsgText') AS lim) y) x JOIN blk b ON b.lang = x.l GROUP BY x.dict, x.j)
FROM AD_Process r WHERE r.AD_Process_ID=53267
ON CONFLICT (AD_CtxHelpMsg_UU) DO UPDATE SET MsgText=EXCLUDED.MsgText, Updated=now() WHERE AD_CtxHelpMsg.MsgText IS DISTINCT FROM EXCLUDED.MsgText;
WITH blk(lang, k, html, more, nextlen) AS (VALUES
  ('en', 1, '<p><strong>5 · Replenishment</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#5-replenishment" target="_blank">5 · Replenishment …</a></p>', 124),
  ('en', 2, '<p>The sale just dropped on-hand. Rather than reorder on every sale, <b>Replenishment</b> is the staged, reviewable action that watches on-hand against each product''s stock policy and proposes what to order — walked in detail in the POS section''s <b>§P-4</b> (the same engine, reached from a friendlier panel there; not repeated here).</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#5-replenishment" target="_blank">5 · Replenishment …</a></p>', 0),
  ('de_DE', 1, '<p><strong>5 · Nachbestellung</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#5-replenishment" target="_blank">5 · Nachbestellung …</a></p>', 125),
  ('de_DE', 2, '<p>Der Verkauf hat den Lagerbestand gerade gesenkt. Statt bei jedem Verkauf nachzubestellen, ist die <b>Nachbestellung</b> der gestufte, prüfbare Schritt, der den Bestand jedes Produkts gegen seine Lagerregel beobachtet und vorschlägt, was zu bestellen ist — ausführlich beschrieben im Abschnitt POS unter <b>§P-4</b> (dieselbe Logik, dort über ein freundlicheres Panel erreichbar; hier nicht wiederholt).</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#5-replenishment" target="_blank">5 · Nachbestellung …</a></p>', 0))
