-- tab 290 Invoice: DV183 + UG6 (twin help 1000005)
INSERT INTO AD_CtxHelp (AD_CtxHelp_ID, AD_CtxHelp_UU, AD_Client_ID, AD_Org_ID, Created, CreatedBy, Updated, UpdatedBy, IsActive, CtxType, Name, Description)
SELECT COALESCE((SELECT AD_CtxHelp_ID FROM AD_CtxHelp WHERE AD_CtxHelp_UU='480d15a5-d980-51cc-8eb7-e0f3733b6354'), nextidfunc((SELECT AD_Sequence_ID FROM AD_Sequence WHERE Name='AD_CtxHelp' AND IsTableID='Y')::integer, 'N')), '480d15a5-d980-51cc-8eb7-e0f3733b6354', 0, 0, now(), 100, now(), 100, 'Y', 'T', 'Purchase Invoice and Credit/Debit Note + 6 · Purchase Order → Receipt → Vendor Invoice → Match', 'https://red1oon.github.io/BIMCompiler/ERPUserGuide/#6-purchase-order-receipt-vendor-invoice-match'
ON CONFLICT (AD_CtxHelp_UU) DO UPDATE SET Name=EXCLUDED.Name, Description=EXCLUDED.Description, Updated=now() WHERE (AD_CtxHelp.Name, AD_CtxHelp.Description) IS DISTINCT FROM (EXCLUDED.Name, EXCLUDED.Description);
WITH blk(lang, k, html, more, nextlen) AS (VALUES
  ('en', 1, '<p><strong>Purchase Invoice and Credit/Debit Note</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Purchase Invoice and Credit/Debit Note …</a></p>', 140),
  ('en', 2, '<p><b>Before you start.</b> These must exist first: Target Document Type (<b>Document Type</b>), <b>Business Partner</b>, Partner Location (<b>Business Partner</b>), <b>Price List</b>, <b>Payment Term</b>.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Purchase Invoice and Credit/Debit Note …</a></p>', 140),
  ('en', 3, '<p><b>Do it.</b> Fill <b>Invoice</b>, then <b>Invoice Line</b>, <b>Invoice Tax</b>, <b>Payment Schedule</b>, <b>Allocation</b>; then the Document Action <b>Complete</b>.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Purchase Invoice and Credit/Debit Note …</a></p>', 140),
  ('en', 4, '<p><b>What Complete does.</b></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Purchase Invoice and Credit/Debit Note …</a></p>', 140),
  ('en', 5, '<ul><li>Payment Rule On Credit, Direct Debit: creates the invoice payment schedule</li><li>Payment Rule Cash: creates and completes a cash payment for the invoice total</li><li>Creates a receipt-to-invoice match for each line with a receipt line ✓</li><li>Creates a purchase order match for each invoice line with a product</li><li>Subtracts invoice total from partner open balance (cash rule non-POS excepted)</li><li>Offers Close as the next document action</li></ul>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Purchase Invoice and Credit/Debit Note …</a></p>', 140),
  ('en', 6, '<p><b>When it refuses</b>, legacy says: “No Document Lines found”; “No Document Type”; “Error calculating Tax”; “Error in payment schedule”; “No account defined for this organization / currency”; “No document type”; “Cannot Complete the Payment : [… ] …”; “Could not update Order Line”; “Could not create PO Matching”; “Could not update RMA Line”; “Could not update Business Partner User”; “InvoicedAmt: … &lt;&gt; AuthorizedAmt: …”.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Purchase Invoice and Credit/Debit Note …</a></p>', 140),
  ('en', 7, '<p><i>Read from iDempiere''s MInvoice.java and the dictionary. ✓ = seen in a legacy run of 2026-11-23.</i></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Purchase Invoice and Credit/Debit Note …</a></p>', 190),
  ('en', 8, '<p><strong>6 · Purchase Order → Receipt → Vendor Invoice → Match</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#6-purchase-order-receipt-vendor-invoice-match" target="_blank">6 · Purchase Order → Receipt → Vendor Invoice → Match …</a></p>', 190),
  ('en', 9, '<p>Accepting a replenishment proposal (or creating one by hand, ⌂ → Purchasing → <b>Purchase Order</b>) and completing it is the buy-side mirror of step 1. It flows the same way in reverse:</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#6-purchase-order-receipt-vendor-invoice-match" target="_blank">6 · Purchase Order → Receipt → Vendor Invoice → Match …</a></p>', 190),
  ('en', 10, '<ul><li><b><b>Purchase Order</b></b> — completes; under this seed''s configuration (commitment accounting off) it posts no commitment/reservation entry — an honest, config-derived ∅, not a gap.</li><li><b>Receipt</b> (<code><b>M_InOut</b></code>, incoming) — stock arrives, on-hand rises.</li><li><b>Vendor Invoice</b> — posts DR <b>Inventory Clearing</b> / CR <b>Vendor Liability</b>.</li><li><b>Match</b> (<code><b>M_MatchInv</b></code>) — clears the Inventory-Clearing/Not-Invoiced-Receipts pair the receipt and invoice each opened, including any invoice-price-variance split against on-hand at match time. <code><b>M_MatchPO</b></code>''s own leg stays an honest ∅ under this seed''s Average costing (the variance-posting branch only fires under Standard costing) — a config fact, proven by flipping it in the witness, not assumed.</li></ul>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#6-purchase-order-receipt-vendor-invoice-match" target="_blank">6 · Purchase Order → Receipt → Vendor Invoice → Match …</a></p>', 0),
  ('de_DE', 1, '<p><strong>6 · Bestellung → Wareneingang → Lieferantenrechnung → Zuordnung</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#6-purchase-order-receipt-vendor-invoice-match" target="_blank">6 · Bestellung → Wareneingang → Lieferantenrechnung → Zuordnung …</a></p>', 200),
  ('de_DE', 2, '<p>Einen Nachbestellungsvorschlag annehmen (oder eine Bestellung von Hand anlegen, ⌂ → Einkauf → <b><b>Bestellung</b></b>) und fertigstellen ist das Spiegelbild von Schritt 1 auf der Einkaufsseite. Es läuft genauso, nur umgekehrt:</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#6-purchase-order-receipt-vendor-invoice-match" target="_blank">6 · Bestellung → Wareneingang → Lieferantenrechnung → Zuordnung …</a></p>', 200),
  ('de_DE', 3, '<ul><li><b><b>Bestellung</b></b> — wird fertiggestellt; mit der Konfiguration dieser Daten (Obligo-Buchhaltung aus) bucht sie keinen Obligo- oder Reservierungseintrag — ein ehrliches, aus der Konfiguration folgendes ∅, keine Lücke.</li><li><b><b>Wareneingang</b></b> (<code>M_InOut</code>, eingehend) — die Ware kommt an, der Bestand steigt.</li><li><b><b>Rechnung (Lieferant)</b></b> — bucht Soll <b>Verrechnung Wareneingang</b> / Haben <b>Verbindlichkeiten</b>.</li><li><b>Zuordnung</b> (<code>M_MatchInv</code>) — gleicht das Paar Verrechnung Wareneingang / nicht fakturierte Eingänge aus, das Eingang und Rechnung jeweils eröffnet haben, einschließlich einer Preisabweichung der Rechnung, aufgeteilt gegen den Bestand zum Zeitpunkt der Zuordnung. Die eigene Buchung von <code>M_MatchPO</code> bleibt mit der Durchschnittskostenrechnung dieser Daten ein ehrliches ∅ (der Zweig für Abweichungsbuchungen greift nur bei Standardkosten) — eine Tatsache der Konfiguration, im Witness durch Umschalten bewiesen, nicht angenommen.</li></ul>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#6-purchase-order-receipt-vendor-invoice-match" target="_blank">6 · Bestellung → Wareneingang → Lieferantenrechnung → Zuordnung …</a></p>', 140),
  ('de_DE', 4, '<p><strong>Purchase Invoice and Credit/Debit Note</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Purchase Invoice and Credit/Debit Note …</a></p>', 140),
  ('de_DE', 5, '<p><b>Before you start.</b> These must exist first: Target Document Type (<b>Document Type</b>), <b>Business Partner</b>, Partner Location (<b>Business Partner</b>), <b>Price List</b>, <b>Payment Term</b>.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Purchase Invoice and Credit/Debit Note …</a></p>', 140),
  ('de_DE', 6, '<p><b>Do it.</b> Fill <b>Invoice</b>, then <b>Invoice Line</b>, <b>Invoice Tax</b>, <b>Payment Schedule</b>, <b>Allocation</b>; then the Document Action <b>Complete</b>.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Purchase Invoice and Credit/Debit Note …</a></p>', 140),
  ('de_DE', 7, '<p><b>What Complete does.</b></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Purchase Invoice and Credit/Debit Note …</a></p>', 140),
  ('de_DE', 8, '<ul><li>Payment Rule On Credit, Direct Debit: creates the invoice payment schedule</li><li>Payment Rule Cash: creates and completes a cash payment for the invoice total</li><li>Creates a receipt-to-invoice match for each line with a receipt line ✓</li><li>Creates a purchase order match for each invoice line with a product</li><li>Subtracts invoice total from partner open balance (cash rule non-POS excepted)</li><li>Offers Close as the next document action</li></ul>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Purchase Invoice and Credit/Debit Note …</a></p>', 140),
  ('de_DE', 9, '<p><b>When it refuses</b>, legacy says: “No Document Lines found”; “No Document Type”; “Error calculating Tax”; “Error in payment schedule”; “No account defined for this organization / currency”; “No document type”; “Cannot Complete the Payment : [… ] …”; “Could not update Order Line”; “Could not create PO Matching”; “Could not update RMA Line”; “Could not update Business Partner User”; “InvoicedAmt: … &lt;&gt; AuthorizedAmt: …”.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Purchase Invoice and Credit/Debit Note …</a></p>', 140),
  ('de_DE', 10, '<p><i>Read from iDempiere''s MInvoice.java and the dictionary. ✓ = seen in a legacy run of 2026-11-23.</i></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Purchase Invoice and Credit/Debit Note …</a></p>', 0))
