SELECT COALESCE((SELECT AD_CtxHelpMsg_ID FROM AD_CtxHelpMsg WHERE AD_CtxHelpMsg_UU='683b047e-3942-59c9-a14f-dae2b3f55850'), nextidfunc((SELECT AD_Sequence_ID FROM AD_Sequence WHERE Name='AD_CtxHelpMsg' AND IsTableID='Y')::integer, 'N')), '683b047e-3942-59c9-a14f-dae2b3f55850', toRecordId('AD_CtxHelp', '480d15a5-d980-51cc-8eb7-e0f3733b6354'), 0, 0, now(), 100, now(), 100, 'Y', (SELECT x.dict || COALESCE(string_agg(b.html, '' ORDER BY b.k) FILTER (WHERE b.k <= x.j), '') || COALESCE(max(b.more) FILTER (WHERE b.k = x.j + 1), '') FROM (SELECT y.dict, y.l, COALESCE((SELECT min(c.k) FROM (SELECT k, sum(length(html)) OVER (ORDER BY k) AS cum, nextlen FROM blk WHERE lang = y.l) c WHERE length(y.dict) + c.cum + c.nextlen > y.lim) - 1, (SELECT max(k) FROM blk WHERE lang = y.l)) AS j FROM (SELECT '<p><strong>' || r.Name || '</strong></p>' || COALESCE('<p><em>' || NULLIF(r.Description, '') || '</em></p>', '') || COALESCE('<p>' || NULLIF(r.Help, '') || '</p>', '') || '<hr>' AS dict, 'en' AS l, (SELECT c.FieldLength FROM AD_Column c JOIN AD_Table tb ON tb.AD_Table_ID=c.AD_Table_ID WHERE tb.TableName='AD_CtxHelpMsg' AND c.ColumnName='MsgText') AS lim) y) x JOIN blk b ON b.lang = x.l GROUP BY x.dict, x.j)
FROM AD_Tab r WHERE r.AD_Tab_ID=290
ON CONFLICT (AD_CtxHelpMsg_UU) DO UPDATE SET MsgText=EXCLUDED.MsgText, Updated=now() WHERE AD_CtxHelpMsg.MsgText IS DISTINCT FROM EXCLUDED.MsgText;
WITH blk(lang, k, html, more, nextlen) AS (VALUES
  ('en', 1, '<p><strong>Purchase Invoice and Credit/Debit Note</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Purchase Invoice and Credit/Debit Note …</a></p>', 140),
  ('en', 2, '<p><b>Before you start.</b> These must exist first: Target Document Type (<b>Document Type</b>), <b>Business Partner</b>, Partner Location (<b>Business Partner</b>), <b>Price List</b>, <b>Payment Term</b>.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Purchase Invoice and Credit/Debit Note …</a></p>', 140),
  ('en', 3, '<p><b>Do it.</b> Fill <b>Invoice</b>, then <b>Invoice Line</b>, <b>Invoice Tax</b>, <b>Payment Schedule</b>, <b>Allocation</b>; then the Document Action <b>Complete</b>.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Purchase Invoice and Credit/Debit Note …</a></p>', 140),
  ('en', 4, '<p><b>What Complete does.</b></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Purchase Invoice and Credit/Debit Note …</a></p>', 140),
  ('en', 5, '<ul><li>Payment Rule On Credit, Direct Debit: creates the invoice payment schedule</li><li>Payment Rule Cash: creates and completes a cash payment for the invoice total</li><li>Creates a receipt-to-invoice match for each line with a receipt line ✓</li><li>Creates a purchase order match for each invoice line with a product</li><li>Subtracts invoice total from partner open balance (cash rule non-POS excepted)</li><li>Offers Close as the next document action</li></ul>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Purchase Invoice and Credit/Debit Note …</a></p>', 140),
  ('en', 6, '<p><b>When it refuses</b>, legacy says: “No Document Lines found”; “No Document Type”; “Error calculating Tax”; “Error in payment schedule”; “No account defined for this organization / currency”; “No document type”; “Cannot Complete the Payment : [… ] …”; “Could not update Order Line”; “Could not create PO Matching”; “Could not update RMA Line”; “Could not update Business Partner User”; “InvoicedAmt: … &lt;&gt; AuthorizedAmt: …”.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Purchase Invoice and Credit/Debit Note …</a></p>', 140),
  ('en', 7, '<p><i>Read from iDempiere''s MInvoice.java and the dictionary. ✓ = seen in a legacy run of 2026-11-23.</i></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Purchase Invoice and Credit/Debit Note …</a></p>', 190),
  ('en', 8, '<p><strong>6 · Purchase Order → Receipt → Vendor Invoice → Match</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#6-purchase-order-receipt-vendor-invoice-match" target="_blank">6 · Purchase Order → Receipt → Vendor Invoice → Match …</a></p>', 190),
  ('en', 9, '<p>Accepting a replenishment proposal (or creating one by hand, ⌂ → Purchasing → <b>Purchase Order</b>) and completing it is the buy-side mirror of step 1. It flows the same way in reverse:</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#6-purchase-order-receipt-vendor-invoice-match" target="_blank">6 · Purchase Order → Receipt → Vendor Invoice → Match …</a></p>', 190),
  ('en', 10, '<ul><li><b><b>Purchase Order</b></b> — completes; under this seed''s configuration (commitment accounting off) it posts no commitment/reservation entry — an honest, config-derived ∅, not a gap.</li><li><b>Receipt</b> (<code><b>M_InOut</b></code>, incoming) — stock arrives, on-hand rises.</li><li><b>Vendor Invoice</b> — posts DR <b>Inventory Clearing</b> / CR <b>Vendor Liability</b>.</li><li><b>Match</b> (<code><b>M_MatchInv</b></code>) — clears the Inventory-Clearing/Not-Invoiced-Receipts pair the receipt and invoice each opened, including any invoice-price-variance split against on-hand at match time. <code><b>M_MatchPO</b></code>''s own leg stays an honest ∅ under this seed''s Average costing (the variance-posting branch only fires under Standard costing) — a config fact, proven by flipping it in the witness, not assumed.</li></ul>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#6-purchase-order-receipt-vendor-invoice-match" target="_blank">6 · Purchase Order → Receipt → Vendor Invoice → Match …</a></p>', 0),
  ('de_DE', 1, '<p><strong>6 · Bestellung → Wareneingang → Lieferantenrechnung → Zuordnung</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#6-purchase-order-receipt-vendor-invoice-match" target="_blank">6 · Bestellung → Wareneingang → Lieferantenrechnung → Zuordnung …</a></p>', 200),
  ('de_DE', 2, '<p>Einen Nachbestellungsvorschlag annehmen (oder eine Bestellung von Hand anlegen, ⌂ → Einkauf → <b><b>Bestellung</b></b>) und fertigstellen ist das Spiegelbild von Schritt 1 auf der Einkaufsseite. Es läuft genauso, nur umgekehrt:</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#6-purchase-order-receipt-vendor-invoice-match" target="_blank">6 · Bestellung → Wareneingang → Lieferantenrechnung → Zuordnung …</a></p>', 200),
  ('de_DE', 3, '<ul><li><b><b>Bestellung</b></b> — wird fertiggestellt; mit der Konfiguration dieser Daten (Obligo-Buchhaltung aus) bucht sie keinen Obligo- oder Reservierungseintrag — ein ehrliches, aus der Konfiguration folgendes ∅, keine Lücke.</li><li><b><b>Wareneingang</b></b> (<code>M_InOut</code>, eingehend) — die Ware kommt an, der Bestand steigt.</li><li><b><b>Rechnung (Lieferant)</b></b> — bucht Soll <b>Verrechnung Wareneingang</b> / Haben <b>Verbindlichkeiten</b>.</li><li><b>Zuordnung</b> (<code>M_MatchInv</code>) — gleicht das Paar Verrechnung Wareneingang / nicht fakturierte Eingänge aus, das Eingang und Rechnung jeweils eröffnet haben, einschließlich einer Preisabweichung der Rechnung, aufgeteilt gegen den Bestand zum Zeitpunkt der Zuordnung. Die eigene Buchung von <code>M_MatchPO</code> bleibt mit der Durchschnittskostenrechnung dieser Daten ein ehrliches ∅ (der Zweig für Abweichungsbuchungen greift nur bei Standardkosten) — eine Tatsache der Konfiguration, im Witness durch Umschalten bewiesen, nicht angenommen.</li></ul>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#6-purchase-order-receipt-vendor-invoice-match" target="_blank">6 · Bestellung → Wareneingang → Lieferantenrechnung → Zuordnung …</a></p>', 140),
  ('de_DE', 4, '<p><strong>Purchase Invoice and Credit/Debit Note</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Purchase Invoice and Credit/Debit Note …</a></p>', 140),
  ('de_DE', 5, '<p><b>Before you start.</b> These must exist first: Target Document Type (<b>Document Type</b>), <b>Business Partner</b>, Partner Location (<b>Business Partner</b>), <b>Price List</b>, <b>Payment Term</b>.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Purchase Invoice and Credit/Debit Note …</a></p>', 140),
  ('de_DE', 6, '<p><b>Do it.</b> Fill <b>Invoice</b>, then <b>Invoice Line</b>, <b>Invoice Tax</b>, <b>Payment Schedule</b>, <b>Allocation</b>; then the Document Action <b>Complete</b>.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Purchase Invoice and Credit/Debit Note …</a></p>', 140),
  ('de_DE', 7, '<p><b>What Complete does.</b></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Purchase Invoice and Credit/Debit Note …</a></p>', 140),
  ('de_DE', 8, '<ul><li>Payment Rule On Credit, Direct Debit: creates the invoice payment schedule</li><li>Payment Rule Cash: creates and completes a cash payment for the invoice total</li><li>Creates a receipt-to-invoice match for each line with a receipt line ✓</li><li>Creates a purchase order match for each invoice line with a product</li><li>Subtracts invoice total from partner open balance (cash rule non-POS excepted)</li><li>Offers Close as the next document action</li></ul>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Purchase Invoice and Credit/Debit Note …</a></p>', 140),
  ('de_DE', 9, '<p><b>When it refuses</b>, legacy says: “No Document Lines found”; “No Document Type”; “Error calculating Tax”; “Error in payment schedule”; “No account defined for this organization / currency”; “No document type”; “Cannot Complete the Payment : [… ] …”; “Could not update Order Line”; “Could not create PO Matching”; “Could not update RMA Line”; “Could not update Business Partner User”; “InvoicedAmt: … &lt;&gt; AuthorizedAmt: …”.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Purchase Invoice and Credit/Debit Note …</a></p>', 140),
  ('de_DE', 10, '<p><i>Read from iDempiere''s MInvoice.java and the dictionary. ✓ = seen in a legacy run of 2026-11-23.</i></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Purchase Invoice and Credit/Debit Note …</a></p>', 0))
INSERT INTO AD_CtxHelpMsg_Trl (AD_CtxHelpMsg_ID, AD_Language, AD_CtxHelpMsg_Trl_UU, AD_Client_ID, AD_Org_ID, Created, CreatedBy, Updated, UpdatedBy, IsActive, IsTranslated, MsgText)
SELECT toRecordId('AD_CtxHelpMsg', '683b047e-3942-59c9-a14f-dae2b3f55850'), r.AD_Language, generate_uuid(), 0, 0, now(), 100, now(), 100, 'Y', 'N', (SELECT x.dict || COALESCE(string_agg(b.html, '' ORDER BY b.k) FILTER (WHERE b.k <= x.j), '') || COALESCE(max(b.more) FILTER (WHERE b.k = x.j + 1), '') FROM (SELECT y.dict, y.l, COALESCE((SELECT min(c.k) FROM (SELECT k, sum(length(html)) OVER (ORDER BY k) AS cum, nextlen FROM blk WHERE lang = y.l) c WHERE length(y.dict) + c.cum + c.nextlen > y.lim) - 1, (SELECT max(k) FROM blk WHERE lang = y.l)) AS j FROM (SELECT '<p><strong>' || r.Name || '</strong></p>' || COALESCE('<p><em>' || NULLIF(r.Description, '') || '</em></p>', '') || COALESCE('<p>' || NULLIF(r.Help, '') || '</p>', '') || '<hr>' AS dict, CASE WHEN EXISTS (SELECT 1 FROM blk WHERE lang = r.AD_Language) THEN r.AD_Language ELSE 'en' END AS l, (SELECT c.FieldLength FROM AD_Column c JOIN AD_Table tb ON tb.AD_Table_ID=c.AD_Table_ID WHERE tb.TableName='AD_CtxHelpMsg_Trl' AND c.ColumnName='MsgText') AS lim) y) x JOIN blk b ON b.lang = x.l GROUP BY x.dict, x.j)
FROM AD_Tab_Trl r WHERE r.AD_Tab_ID=290
ON CONFLICT (AD_CtxHelpMsg_ID, AD_Language) DO UPDATE SET MsgText=EXCLUDED.MsgText, Updated=now() WHERE AD_CtxHelpMsg_Trl.MsgText IS DISTINCT FROM EXCLUDED.MsgText;
UPDATE AD_Tab SET AD_CtxHelp_ID=toRecordId('AD_CtxHelp', '480d15a5-d980-51cc-8eb7-e0f3733b6354'), Updated=now() WHERE AD_Tab_ID=290 AND AD_CtxHelp_ID IS NULL;

-- tab 328 Bank/Cash Statement: DV194 + UG7 (twin help 1000006)
INSERT INTO AD_CtxHelp (AD_CtxHelp_ID, AD_CtxHelp_UU, AD_Client_ID, AD_Org_ID, Created, CreatedBy, Updated, UpdatedBy, IsActive, CtxType, Name, Description)
SELECT COALESCE((SELECT AD_CtxHelp_ID FROM AD_CtxHelp WHERE AD_CtxHelp_UU='a3fa2108-b913-5d37-8a11-b23fd0a23b5b'), nextidfunc((SELECT AD_Sequence_ID FROM AD_Sequence WHERE Name='AD_CtxHelp' AND IsTableID='Y')::integer, 'N')), 'a3fa2108-b913-5d37-8a11-b23fd0a23b5b', 0, 0, now(), 100, now(), 100, 'Y', 'T', 'Bank/Cash Statement + 7 · Final accounts', 'https://red1oon.github.io/BIMCompiler/ERPUserGuide/#7-final-accounts'
ON CONFLICT (AD_CtxHelp_UU) DO UPDATE SET Name=EXCLUDED.Name, Description=EXCLUDED.Description, Updated=now() WHERE (AD_CtxHelp.Name, AD_CtxHelp.Description) IS DISTINCT FROM (EXCLUDED.Name, EXCLUDED.Description);
WITH blk(lang, k, html, more, nextlen) AS (VALUES
  ('en', 1, '<p><strong>Bank/Cash Statement</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Bank/Cash Statement …</a></p>', 121),
  ('en', 2, '<p><b>Before you start.</b> These must exist first: Bank Account (<b>Bank/Cash</b>), <b>Document Type</b>.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Bank/Cash Statement …</a></p>', 121),
  ('en', 3, '<p><b>Do it.</b> Fill <b>Bank/Cash Statement</b>, then <b>Statement Line</b>; then the Document Action <b>Complete</b>.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Bank/Cash Statement …</a></p>', 121),
  ('en', 4, '<p><b>What Complete does.</b></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Bank/Cash Statement …</a></p>', 121),
  ('en', 5, '<ul><li>Bank statement line with Payment: marks the payment of the statement line reconciled</li><li>Bank statement line with Deposit Batch: marks every payment of the deposit batch reconciled</li><li>Adds the statement difference to the bank account current balance ✓</li><li>Offers Close as the next document action</li></ul>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Bank/Cash Statement …</a></p>', 121),
  ('en', 6, '<p><b>When it refuses</b>, legacy says: “Discount” ✓; “No Document Lines found”.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Bank/Cash Statement …</a></p>', 121),
  ('en', 7, '<p><i>Read from iDempiere''s MBankStatement.java and the dictionary. ✓ = seen in a legacy run of 2026-11-23.</i></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Bank/Cash Statement …</a></p>', 126),
  ('en', 8, '<p><strong>7 · Final accounts</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#7-final-accounts" target="_blank">7 · Final accounts …</a></p>', 126),
  ('en', 9, '<p>Two more postings close the period: a <b><b>GL Journal</b></b> for anything that isn''t a document (a manual accrual, an inter-org transfer) and a <b><b>Bank Statement</b></b> reconciling the bank''s own records against what the ledger expects. Once every document for the period is posted, the period''s <code>fact_acct</code> <b>is</b> the ledger — there is no separate "close" step that recomputes anything; Trial Balance is a live fold of the same rows, and it balances to the cent.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#7-final-accounts" target="_blank">7 · Final accounts …</a></p>', 0),
  ('de_DE', 1, '<p><strong>7 · Abschluss</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#7-final-accounts" target="_blank">7 · Abschluss …</a></p>', 121),
  ('de_DE', 2, '<p>Zwei weitere Buchungen schließen die Periode: ein <b><b>Journal</b></b> für alles, was kein Beleg ist (eine manuelle Abgrenzung, eine Übertragung zwischen Organisationen), und ein <b><b>Bankauszug</b></b>, der die Aufzeichnungen der Bank mit dem abgleicht, was das Hauptbuch erwartet. Sobald jeder Beleg der Periode gebucht ist, <b>ist</b> <code>fact_acct</code> der Periode das Hauptbuch — es gibt keinen eigenen Abschlussschritt, der etwas neu berechnet; die Rohbilanz ist eine laufende Auswertung derselben Zeilen und geht auf den Cent auf.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#7-final-accounts" target="_blank">7 · Abschluss …</a></p>', 121),
  ('de_DE', 3, '<p><strong>Bank/Cash Statement</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Bank/Cash Statement …</a></p>', 121),
  ('de_DE', 4, '<p><b>Before you start.</b> These must exist first: Bank Account (<b>Bank/Cash</b>), <b>Document Type</b>.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Bank/Cash Statement …</a></p>', 121),
  ('de_DE', 5, '<p><b>Do it.</b> Fill <b>Bank/Cash Statement</b>, then <b>Statement Line</b>; then the Document Action <b>Complete</b>.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Bank/Cash Statement …</a></p>', 121),
  ('de_DE', 6, '<p><b>What Complete does.</b></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Bank/Cash Statement …</a></p>', 121),
  ('de_DE', 7, '<ul><li>Bank statement line with Payment: marks the payment of the statement line reconciled</li><li>Bank statement line with Deposit Batch: marks every payment of the deposit batch reconciled</li><li>Adds the statement difference to the bank account current balance ✓</li><li>Offers Close as the next document action</li></ul>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Bank/Cash Statement …</a></p>', 121),
  ('de_DE', 8, '<p><b>When it refuses</b>, legacy says: “Discount” ✓; “No Document Lines found”.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Bank/Cash Statement …</a></p>', 121),
  ('de_DE', 9, '<p><i>Read from iDempiere''s MBankStatement.java and the dictionary. ✓ = seen in a legacy run of 2026-11-23.</i></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Bank/Cash Statement …</a></p>', 0))
INSERT INTO AD_CtxHelpMsg (AD_CtxHelpMsg_ID, AD_CtxHelpMsg_UU, AD_CtxHelp_ID, AD_Client_ID, AD_Org_ID, Created, CreatedBy, Updated, UpdatedBy, IsActive, MsgText)
SELECT COALESCE((SELECT AD_CtxHelpMsg_ID FROM AD_CtxHelpMsg WHERE AD_CtxHelpMsg_UU='5659d136-e2ea-5f05-ad39-cca99c4ae513'), nextidfunc((SELECT AD_Sequence_ID FROM AD_Sequence WHERE Name='AD_CtxHelpMsg' AND IsTableID='Y')::integer, 'N')), '5659d136-e2ea-5f05-ad39-cca99c4ae513', toRecordId('AD_CtxHelp', 'a3fa2108-b913-5d37-8a11-b23fd0a23b5b'), 0, 0, now(), 100, now(), 100, 'Y', (SELECT x.dict || COALESCE(string_agg(b.html, '' ORDER BY b.k) FILTER (WHERE b.k <= x.j), '') || COALESCE(max(b.more) FILTER (WHERE b.k = x.j + 1), '') FROM (SELECT y.dict, y.l, COALESCE((SELECT min(c.k) FROM (SELECT k, sum(length(html)) OVER (ORDER BY k) AS cum, nextlen FROM blk WHERE lang = y.l) c WHERE length(y.dict) + c.cum + c.nextlen > y.lim) - 1, (SELECT max(k) FROM blk WHERE lang = y.l)) AS j FROM (SELECT '<p><strong>' || r.Name || '</strong></p>' || COALESCE('<p><em>' || NULLIF(r.Description, '') || '</em></p>', '') || COALESCE('<p>' || NULLIF(r.Help, '') || '</p>', '') || '<hr>' AS dict, 'en' AS l, (SELECT c.FieldLength FROM AD_Column c JOIN AD_Table tb ON tb.AD_Table_ID=c.AD_Table_ID WHERE tb.TableName='AD_CtxHelpMsg' AND c.ColumnName='MsgText') AS lim) y) x JOIN blk b ON b.lang = x.l GROUP BY x.dict, x.j)
FROM AD_Tab r WHERE r.AD_Tab_ID=328
ON CONFLICT (AD_CtxHelpMsg_UU) DO UPDATE SET MsgText=EXCLUDED.MsgText, Updated=now() WHERE AD_CtxHelpMsg.MsgText IS DISTINCT FROM EXCLUDED.MsgText;
