  ('de_DE', 4, '<p><b>Before you start.</b> These must exist first: Bank Account (<b>Bank/Cash</b>), <b>Document Type</b>.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Bank/Cash Statement …</a></p>', 121),
  ('de_DE', 5, '<p><b>Do it.</b> Fill <b>Bank/Cash Statement</b>, then <b>Statement Line</b>; then the Document Action <b>Complete</b>.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Bank/Cash Statement …</a></p>', 121),
  ('de_DE', 6, '<p><b>What Complete does.</b></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Bank/Cash Statement …</a></p>', 121),
  ('de_DE', 7, '<ul><li>Bank statement line with Payment: marks the payment of the statement line reconciled</li><li>Bank statement line with Deposit Batch: marks every payment of the deposit batch reconciled</li><li>Adds the statement difference to the bank account current balance ✓</li><li>Offers Close as the next document action</li></ul>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Bank/Cash Statement …</a></p>', 121),
  ('de_DE', 8, '<p><b>When it refuses</b>, legacy says: “Discount” ✓; “No Document Lines found”.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Bank/Cash Statement …</a></p>', 121),
  ('de_DE', 9, '<p><i>Read from iDempiere''s MBankStatement.java and the dictionary. ✓ = seen in a legacy run of 2026-11-23.</i></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Bank/Cash Statement …</a></p>', 0))
INSERT INTO AD_CtxHelpMsg_Trl (AD_CtxHelpMsg_ID, AD_Language, AD_CtxHelpMsg_Trl_UU, AD_Client_ID, AD_Org_ID, Created, CreatedBy, Updated, UpdatedBy, IsActive, IsTranslated, MsgText)
SELECT toRecordId('AD_CtxHelpMsg', '5659d136-e2ea-5f05-ad39-cca99c4ae513'), r.AD_Language, generate_uuid(), 0, 0, now(), 100, now(), 100, 'Y', 'N', (SELECT x.dict || COALESCE(string_agg(b.html, '' ORDER BY b.k) FILTER (WHERE b.k <= x.j), '') || COALESCE(max(b.more) FILTER (WHERE b.k = x.j + 1), '') FROM (SELECT y.dict, y.l, COALESCE((SELECT min(c.k) FROM (SELECT k, sum(length(html)) OVER (ORDER BY k) AS cum, nextlen FROM blk WHERE lang = y.l) c WHERE length(y.dict) + c.cum + c.nextlen > y.lim) - 1, (SELECT max(k) FROM blk WHERE lang = y.l)) AS j FROM (SELECT '<p><strong>' || r.Name || '</strong></p>' || COALESCE('<p><em>' || NULLIF(r.Description, '') || '</em></p>', '') || COALESCE('<p>' || NULLIF(r.Help, '') || '</p>', '') || '<hr>' AS dict, CASE WHEN EXISTS (SELECT 1 FROM blk WHERE lang = r.AD_Language) THEN r.AD_Language ELSE 'en' END AS l, (SELECT c.FieldLength FROM AD_Column c JOIN AD_Table tb ON tb.AD_Table_ID=c.AD_Table_ID WHERE tb.TableName='AD_CtxHelpMsg_Trl' AND c.ColumnName='MsgText') AS lim) y) x JOIN blk b ON b.lang = x.l GROUP BY x.dict, x.j)
FROM AD_Tab_Trl r WHERE r.AD_Tab_ID=328
ON CONFLICT (AD_CtxHelpMsg_ID, AD_Language) DO UPDATE SET MsgText=EXCLUDED.MsgText, Updated=now() WHERE AD_CtxHelpMsg_Trl.MsgText IS DISTINCT FROM EXCLUDED.MsgText;
UPDATE AD_Tab SET AD_CtxHelp_ID=toRecordId('AD_CtxHelp', 'a3fa2108-b913-5d37-8a11-b23fd0a23b5b'), Updated=now() WHERE AD_Tab_ID=328 AND AD_CtxHelp_ID IS NULL;

-- tab 372 Financial Report: DV216 + UG8 (twin help 1000007)
INSERT INTO AD_CtxHelp (AD_CtxHelp_ID, AD_CtxHelp_UU, AD_Client_ID, AD_Org_ID, Created, CreatedBy, Updated, UpdatedBy, IsActive, CtxType, Name, Description)
SELECT COALESCE((SELECT AD_CtxHelp_ID FROM AD_CtxHelp WHERE AD_CtxHelp_UU='83765705-ba68-5d84-8dd7-17a23550b2d4'), nextidfunc((SELECT AD_Sequence_ID FROM AD_Sequence WHERE Name='AD_CtxHelp' AND IsTableID='Y')::integer, 'N')), '83765705-ba68-5d84-8dd7-17a23550b2d4', 0, 0, now(), 100, now(), 100, 'Y', 'T', 'Financial Report + 8 · Financial reporting', 'https://red1oon.github.io/BIMCompiler/ERPUserGuide/#8-financial-reporting'
ON CONFLICT (AD_CtxHelp_UU) DO UPDATE SET Name=EXCLUDED.Name, Description=EXCLUDED.Description, Updated=now() WHERE (AD_CtxHelp.Name, AD_CtxHelp.Description) IS DISTINCT FROM (EXCLUDED.Name, EXCLUDED.Description);
WITH blk(lang, k, html, more, nextlen) AS (VALUES
  ('en', 1, '<p><strong>Financial Report</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Financial Report …</a></p>', 118),
  ('en', 2, '<p><b>Before you start.</b> These must exist first: <b>Accounting Schema</b>, Calendar (<b>Calendar Year and Period</b>), <b>Report Line Set</b>, <b>Report Column Set</b>.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Financial Report …</a></p>', 118),
  ('en', 3, '<p><b>Do it.</b> Fill <b>Financial Report</b>.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Financial Report …</a></p>', 118),
  ('en', 4, '<p><i>Read from the dictionary.</i></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Financial Report …</a></p>', 136),
  ('en', 5, '<p><strong>8 · Financial reporting</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#8-financial-reporting" target="_blank">8 · Financial reporting …</a></p>', 136),
  ('en', 6, '<p>From here, everything is read-only fold: <b>Balance Sheet</b>, <b>Income Statement</b>, <b>Cash Flow</b>, and <b>Trial Balance</b> are all oracle-equivalent to the real ledger (§8 <i>Financial Reporting</i>, below, has the per-report cell counts), and the same ledger is what the <b>NinjaExcel</b> workbook lens (§8, "Excel Report") binds into your own spreadsheet layout.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#8-financial-reporting" target="_blank">8 · Financial reporting …</a></p>', 0),
  ('de_DE', 1, '<p><strong>8 · Finanzberichte</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#8-financial-reporting" target="_blank">8 · Finanzberichte …</a></p>', 131),
  ('de_DE', 2, '<p>Ab hier ist alles nur lesende Auswertung: <b>Bilanz</b>, <b>Gewinn- und Verlustrechnung</b>, <b>Kapitalflussrechnung</b> und <b>Rohbilanz</b> sind alle gleichwertig zum echten Hauptbuch (§8 <i>Finanzberichte</i> weiter unten nennt die Zellenzahlen je Bericht), und dasselbe Hauptbuch bindet die Arbeitsmappen-Ansicht <b>NinjaExcel</b> (§8, „Excel Report“) in Ihr eigenes Tabellenlayout ein. Der <b><b>Finanzbericht</b></b> ist das Fenster dazu.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#8-financial-reporting" target="_blank">8 · Finanzberichte …</a></p>', 118),
  ('de_DE', 3, '<p><strong>Financial Report</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Financial Report …</a></p>', 118),
  ('de_DE', 4, '<p><b>Before you start.</b> These must exist first: <b>Accounting Schema</b>, Calendar (<b>Calendar Year and Period</b>), <b>Report Line Set</b>, <b>Report Column Set</b>.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Financial Report …</a></p>', 118),
  ('de_DE', 5, '<p><b>Do it.</b> Fill <b>Financial Report</b>.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Financial Report …</a></p>', 118),
  ('de_DE', 6, '<p><i>Read from the dictionary.</i></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Financial Report …</a></p>', 0))
