ON CONFLICT (AD_CtxHelp_UU) DO UPDATE SET Name=EXCLUDED.Name, Description=EXCLUDED.Description, Updated=now() WHERE (AD_CtxHelp.Name, AD_CtxHelp.Description) IS DISTINCT FROM (EXCLUDED.Name, EXCLUDED.Description);
WITH blk(lang, k, html, more, nextlen) AS (VALUES
  ('en', 1, '<p><strong>Warehouse and Locators</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Warehouse and Locators …</a></p>', 124),
  ('en', 2, '<p><b>Needed by.</b> Each of these asks for one on its header: <b>Inventory Decrease/Increase</b>, <b>Sales Order</b>, <b>Requisition</b>, <b>Purchase Order</b>, <b>Physical Inventory</b>.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Warehouse and Locators …</a></p>', 124),
  ('en', 3, '<p><b>Do it.</b> Fill <b>Warehouse</b>, then <b>Locator</b>, <b>Replenish</b>, <b>Accounting</b>.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Warehouse and Locators …</a></p>', 124),
  ('en', 4, '<p><i>Read from the dictionary.</i></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Warehouse and Locators …</a></p>', 186),
  ('en', 5, '<p><strong>Step 6 · Products, prices, tax and payment terms</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERP_FirstSetup/#step-6-products-prices-tax-and-payment-terms" target="_blank">Step 6 · Products, prices, tax and payment terms …</a></p>', 186),
  ('en', 6, '<ul><li><b><b>Warehouse</b></b>: the setup made one, <b>HQ Warehouse</b>, with one locator. It shows in <b><b>Warehouse and Locators</b></b> (window 139).</li><li><b><b>Product</b></b> (window 140) needs a <b><b>Tax Category</b></b>. The setup created one (<i>Sales Tax</i> for a United States company), and it is the only one offered in your company.</li><li><b>Payment terms</b>: the setup created <b>Immediate</b> (0 days, the default), as iDempiere''s setup does.</li></ul>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERP_FirstSetup/#step-6-products-prices-tax-and-payment-terms" target="_blank">Step 6 · Products, prices, tax and payment terms …</a></p>', 186),
  ('en', 7, '<p>The drop-down lists on a new record show only <b>your own company''s</b> records and shared <code>*</code> records, as in iDempiere.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERP_FirstSetup/#step-6-products-prices-tax-and-payment-terms" target="_blank">Step 6 · Products, prices, tax and payment terms …</a></p>', 0))
