INSERT INTO AD_CtxHelp (AD_CtxHelp_ID, AD_CtxHelp_UU, AD_Client_ID, AD_Org_ID, Created, CreatedBy, Updated, UpdatedBy, IsActive, CtxType, Name, Description)
SELECT COALESCE((SELECT AD_CtxHelp_ID FROM AD_CtxHelp WHERE AD_CtxHelp_UU='03f7acd4-c92c-5691-b512-e8b7e7e88fca'), nextidfunc((SELECT AD_Sequence_ID FROM AD_Sequence WHERE Name='AD_CtxHelp' AND IsTableID='Y')::integer, 'N')), '03f7acd4-c92c-5691-b512-e8b7e7e88fca', 0, 0, now(), 100, now(), 100, 'Y', 'T', 'Step 6a · Give your customer an address', 'https://red1oon.github.io/BIMCompiler/ERP_FirstSetup/#step-6a-give-your-customer-an-address'
ON CONFLICT (AD_CtxHelp_UU) DO UPDATE SET Name=EXCLUDED.Name, Description=EXCLUDED.Description, Updated=now() WHERE (AD_CtxHelp.Name, AD_CtxHelp.Description) IS DISTINCT FROM (EXCLUDED.Name, EXCLUDED.Description);
WITH blk(lang, k, html, more, nextlen) AS (VALUES
  ('en', 1, '<p><strong>Step 6a · Give your customer an address</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERP_FirstSetup/#step-6a-give-your-customer-an-address" target="_blank">Step 6a · Give your customer an address …</a></p>', 170),
  ('en', 2, '<p>A sales order needs the customer''s address, as in iDempiere (without one the order is refused: <i>BPartnerNoShipToAddress</i>).</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERP_FirstSetup/#step-6a-give-your-customer-an-address" target="_blank">Step 6a · Give your customer an address …</a></p>', 170),
  ('en', 3, '<ol><li value="1">In <b><b>Business Partner</b></b>, select your customer (e.g. <code>Acme Retail Sdn Bhd</code>) and open the <b><b>Location</b></b> tab. Click <b>New record</b>.</li><li value="2">Next to <b><b>Address</b></b>, click <b>Address…</b>. Fill in <b>Address 1</b>, <b><b>City</b></b>, <b>Postal</b> and pick the <b><b>Country</b></b> (and the <b><b>Region</b></b> if the country uses regions). Click <b>OK</b>. The address is saved at once, as iDempiere''s address dialog does.</li><li value="3">Click <b>Save</b>. The location is named after the city.</li></ol>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERP_FirstSetup/#step-6a-give-your-customer-an-address" target="_blank">Step 6a · Give your customer an address …</a></p>', 0))
