WITH blk(lang, k, html, more, nextlen) AS (VALUES
  ('en', 1, '<p><strong>Step 11b · Aging: who owes you, and since when</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERP_FirstSetup/#step-11b-aging-who-owes-you-and-since-when" target="_blank">Step 11b · Aging: who owes you, and since when …</a></p>', 182),
  ('en', 2, '<ol><li value="1">Open <b>Aging</b> from the menu (or <code>idempiere.html?login=GardenAdmin&amp;process=238</code>).</li><li value="2">Leave <b>Sales Transaction</b> = Y for customers (N for vendors). <b>Statement Date</b> empty means today.</li><li value="3">Click <b>Run</b>. The report lists, per customer and currency, the open amount split into <i>not yet due</i> and <i>past due 1-7 / 8-30 / 31-60 / 61-90 / 91+ days</i>, with a total per currency.</li></ol>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERP_FirstSetup/#step-11b-aging-who-owes-you-and-since-when" target="_blank">Step 11b · Aging: who owes you, and since when …</a></p>', 0))
