  ('en', 2, '<p><b>Do it.</b> Fill <b>Confirmation</b>, then <b>Line</b>; then the Document Action <b>Complete</b>.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Move Confirmation …</a></p>', 119),
