  ('en', 2, '<p><b>Do it.</b> Fill <b>Allocation</b>, then <b>Allocation Line</b>; then the Document Action <b>Complete</b>.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">View Allocation …</a></p>', 117),
  ('en', 3, '<p><b>What Complete does.</b></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">View Allocation …</a></p>', 117),
  ('en', 4, '<ul><li>Allocation Line with Invoice: sets the invoice paid flag from its allocated amount</li><li>Allocation Line with Payment: refreshes the allocated flag of the payment on each line</li><li>Recalculates the open balance of each business partner on the lines</li><li>Offers Close as the next document action</li></ul>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">View Allocation …</a></p>', 117),
  ('en', 5, '<p><b>When it refuses</b>, legacy says: “No Document Lines found”; “No Business Partner”; “Wrong allocation date”.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">View Allocation …</a></p>', 117),
  ('en', 6, '<p><i>Read from iDempiere''s MAllocationHdr.java and the dictionary. ✓ = seen in a legacy run of 2026-11-23.</i></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">View Allocation …</a></p>', 0))
