WITH blk(lang, k, html, more, nextlen) AS (VALUES
  ('en', 1, '<p><strong>Invoice Payment Schedule</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Invoice Payment Schedule …</a></p>', 126),
  ('en', 2, '<p><b>Before you start.</b> These must exist first: <b>Payment Term</b>.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Invoice Payment Schedule …</a></p>', 126),
  ('en', 3, '<p><b>Do it.</b> Fill <b>Invoice</b>, then <b>Payment Schedule</b>; then the Document Action <b>Complete</b>.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Invoice Payment Schedule …</a></p>', 126),
  ('en', 4, '<p><b>What Complete does.</b></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Invoice Payment Schedule …</a></p>', 126),
  ('en', 5, '<ul><li>Payment Rule On Credit, Direct Debit: creates the invoice payment schedule</li><li>Payment Rule Cash: creates and completes a cash payment for the invoice total</li><li>Adds the invoiced quantity to the sales order line ✓</li><li>Prepay Order: allocates completed unallocated prepayments of the order to the invoice</li><li>Adds invoice total to partner open balance (cash rule non-POS excepted) ✓</li><li>Adds invoice total to partner credit used ✓</li><li>Offers Close as the next document action</li></ul>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Invoice Payment Schedule …</a></p>', 126),
  ('en', 6, '<p><b>When it refuses</b>, legacy says: “No Document Lines found”; “No Document Type”; “Error calculating Tax”; “Error in payment schedule”; “No account defined for this organization / currency”; “No document type”; “Cannot Complete the Payment : [… ] …”; “Could not update Order Line”; “Could not create PO Matching”; “Could not update RMA Line”; “Could not update Business Partner User”; “InvoicedAmt: … &lt;&gt; AuthorizedAmt: …”.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Invoice Payment Schedule …</a></p>', 126),
  ('en', 7, '<p><i>Read from iDempiere''s MInvoice.java and the dictionary. ✓ = seen in a legacy run of 2026-11-23.</i></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Invoice Payment Schedule …</a></p>', 0))
