ON CONFLICT (AD_CtxHelp_UU) DO UPDATE SET Name=EXCLUDED.Name, Description=EXCLUDED.Description, Updated=now() WHERE (AD_CtxHelp.Name, AD_CtxHelp.Description) IS DISTINCT FROM (EXCLUDED.Name, EXCLUDED.Description);
WITH blk(lang, k, html, more, nextlen) AS (VALUES
  ('en', 1, '<p><strong>Inventory Move</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Inventory Move …</a></p>', 116),
  ('en', 2, '<p><b>Before you start.</b> These must exist first: <b>Document Type</b>.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Inventory Move …</a></p>', 116),
  ('en', 3, '<p><b>Do it.</b> Fill <b>Move</b>, then <b>Move Line</b>; then the Document Action <b>Complete</b>.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Inventory Move …</a></p>', 116),
  ('en', 4, '<p><b>What Complete does.</b></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Inventory Move …</a></p>', 116),
  ('en', 5, '<ul><li>In Transit: Yes: creates a movement confirmation (if none exists) for an in-transit document type</li><li>Stays In Progress while a movement confirmation is unprocessed</li><li>Takes the line quantity out of the source locator''s on-hand stock (stocked products)</li><li>Adds the line quantity to the destination locator''s on-hand stock (stocked products)</li><li>Offers Close as the next document action</li></ul>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Inventory Move …</a></p>', 116),
  ('en', 6, '<p><b>When it refuses</b>, legacy says: “Period Closed”; “Back-Date transaction not allowed”; “No Document Lines found”; “Line No … : Fill mandatory fields: Attribute Set Instance”; “Line No … : Fill mandatory fields: Attribute Set Instance To”; “Open: Move Confirm”; “More than line qty on attribute tab for line …”; “Cannot correct Inventory OnHand (MA) [… ] - …”; “Transaction From not inserted (MA) [… ] -”; “Transaction To not inserted (MA) [… ] -”; “Transaction To not inserted [… ] -”.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Inventory Move …</a></p>', 116),
  ('en', 7, '<p><i>Read from iDempiere''s MMovement.java and the dictionary. ✓ = seen in a legacy run of 2026-11-23.</i></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Inventory Move …</a></p>', 0))
