-- tab 296 Material Receipt: DV184 + UG6 (twin help 1000082)
INSERT INTO AD_CtxHelp (AD_CtxHelp_ID, AD_CtxHelp_UU, AD_Client_ID, AD_Org_ID, Created, CreatedBy, Updated, UpdatedBy, IsActive, CtxType, Name, Description)
SELECT COALESCE((SELECT AD_CtxHelp_ID FROM AD_CtxHelp WHERE AD_CtxHelp_UU='6c52a0ab-f6bd-5348-8bd5-92cbe3fa97b1'), nextidfunc((SELECT AD_Sequence_ID FROM AD_Sequence WHERE Name='AD_CtxHelp' AND IsTableID='Y')::integer, 'N')), '6c52a0ab-f6bd-5348-8bd5-92cbe3fa97b1', 0, 0, now(), 100, now(), 100, 'Y', 'T', 'Material Receipt + 6 · Purchase Order → Receipt → Vendor Invoice → Match', 'https://red1oon.github.io/BIMCompiler/ERPUserGuide/#6-purchase-order-receipt-vendor-invoice-match'
ON CONFLICT (AD_CtxHelp_UU) DO UPDATE SET Name=EXCLUDED.Name, Description=EXCLUDED.Description, Updated=now() WHERE (AD_CtxHelp.Name, AD_CtxHelp.Description) IS DISTINCT FROM (EXCLUDED.Name, EXCLUDED.Description);
WITH blk(lang, k, html, more, nextlen) AS (VALUES
  ('en', 1, '<p><strong>Material Receipt</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Material Receipt …</a></p>', 118),
  ('en', 2, '<p><b>Before you start.</b> These must exist first: <b>Business Partner</b>, Partner Location (<b>Business Partner</b>).</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Material Receipt …</a></p>', 118),
  ('en', 3, '<p><b>Do it.</b> Fill <b>Material Receipt</b>, then <b>Receipt Line</b>; then the Document Action <b>Complete</b>.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Material Receipt …</a></p>', 118),
  ('en', 4, '<p><b>What Complete does.</b></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Material Receipt …</a></p>', 118),
  ('en', 5, '<ul><li>Ship/Receipt Confirmation: Yes: creates a ship/receipt confirmation (after the pick/QA one when both are on)</li><li>Stays In Progress while a non-customer confirmation is unprocessed</li><li>Movement Type Customer Shipment, Vendor Returns: takes the line quantity out of the locator''s on-hand stock (stocked products)</li><li>Movement Type Customer Returns, Vendor Receipts: adds the line quantity to the locator''s on-hand stock (stocked products)</li><li>Reduces the product''s ordered stock for the order line''s warehouse</li><li>Creates an invoice-receipt match when the receipt line has an invoice line</li><li>Creates a PO match linking the receipt line to its order line ✓</li><li>Offers Close as the next document action</li></ul>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Material Receipt …</a></p>', 118),
  ('en', 6, '<p><b>When it refuses</b>, legacy says: “Either Order or RMA can be process on this document.”; “Period Closed”; “Back-Date transaction not allowed”; “No Document Lines found”; “Attribute Set Mandatory (Line No #… , Product=… )”; “Open: Ship/Receipt Confirmation”; “Insufficient Stock Coverage. A shipment should not be allowed if there is insufficient stock before the shipment’s movement date.”; “More than line qty on attribute tab for line …”; “Cannot correct Inventory OnHand (MA) [… ] - …”; “Could not create Material Transaction (MA) [… ]”; and 8 more in MInOut.java.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Material Receipt …</a></p>', 118),
  ('en', 7, '<p><i>Read from iDempiere''s MInOut.java and the dictionary. ✓ = seen in a legacy run of 2026-11-23.</i></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Material Receipt …</a></p>', 190),
  ('en', 8, '<p><strong>6 · Purchase Order → Receipt → Vendor Invoice → Match</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#6-purchase-order-receipt-vendor-invoice-match" target="_blank">6 · Purchase Order → Receipt → Vendor Invoice → Match …</a></p>', 190),
  ('en', 9, '<p>Accepting a replenishment proposal (or creating one by hand, ⌂ → Purchasing → <b>Purchase Order</b>) and completing it is the buy-side mirror of step 1. It flows the same way in reverse:</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#6-purchase-order-receipt-vendor-invoice-match" target="_blank">6 · Purchase Order → Receipt → Vendor Invoice → Match …</a></p>', 190),
  ('en', 10, '<ul><li><b><b>Purchase Order</b></b> — completes; under this seed''s configuration (commitment accounting off) it posts no commitment/reservation entry — an honest, config-derived ∅, not a gap.</li><li><b>Receipt</b> (<code><b>M_InOut</b></code>, incoming) — stock arrives, on-hand rises.</li><li><b>Vendor Invoice</b> — posts DR <b>Inventory Clearing</b> / CR <b>Vendor Liability</b>.</li><li><b>Match</b> (<code><b>M_MatchInv</b></code>) — clears the Inventory-Clearing/Not-Invoiced-Receipts pair the receipt and invoice each opened, including any invoice-price-variance split against on-hand at match time. <code><b>M_MatchPO</b></code>''s own leg stays an honest ∅ under this seed''s Average costing (the variance-posting branch only fires under Standard costing) — a config fact, proven by flipping it in the witness, not assumed.</li></ul>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#6-purchase-order-receipt-vendor-invoice-match" target="_blank">6 · Purchase Order → Receipt → Vendor Invoice → Match …</a></p>', 0),
  ('de_DE', 1, '<p><strong>6 · Bestellung → Wareneingang → Lieferantenrechnung → Zuordnung</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#6-purchase-order-receipt-vendor-invoice-match" target="_blank">6 · Bestellung → Wareneingang → Lieferantenrechnung → Zuordnung …</a></p>', 200),
  ('de_DE', 2, '<p>Einen Nachbestellungsvorschlag annehmen (oder eine Bestellung von Hand anlegen, ⌂ → Einkauf → <b><b>Bestellung</b></b>) und fertigstellen ist das Spiegelbild von Schritt 1 auf der Einkaufsseite. Es läuft genauso, nur umgekehrt:</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#6-purchase-order-receipt-vendor-invoice-match" target="_blank">6 · Bestellung → Wareneingang → Lieferantenrechnung → Zuordnung …</a></p>', 200),
  ('de_DE', 3, '<ul><li><b><b>Bestellung</b></b> — wird fertiggestellt; mit der Konfiguration dieser Daten (Obligo-Buchhaltung aus) bucht sie keinen Obligo- oder Reservierungseintrag — ein ehrliches, aus der Konfiguration folgendes ∅, keine Lücke.</li><li><b><b>Wareneingang</b></b> (<code>M_InOut</code>, eingehend) — die Ware kommt an, der Bestand steigt.</li><li><b><b>Rechnung (Lieferant)</b></b> — bucht Soll <b>Verrechnung Wareneingang</b> / Haben <b>Verbindlichkeiten</b>.</li><li><b>Zuordnung</b> (<code>M_MatchInv</code>) — gleicht das Paar Verrechnung Wareneingang / nicht fakturierte Eingänge aus, das Eingang und Rechnung jeweils eröffnet haben, einschließlich einer Preisabweichung der Rechnung, aufgeteilt gegen den Bestand zum Zeitpunkt der Zuordnung. Die eigene Buchung von <code>M_MatchPO</code> bleibt mit der Durchschnittskostenrechnung dieser Daten ein ehrliches ∅ (der Zweig für Abweichungsbuchungen greift nur bei Standardkosten) — eine Tatsache der Konfiguration, im Witness durch Umschalten bewiesen, nicht angenommen.</li></ul>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#6-purchase-order-receipt-vendor-invoice-match" target="_blank">6 · Bestellung → Wareneingang → Lieferantenrechnung → Zuordnung …</a></p>', 118),
  ('de_DE', 4, '<p><strong>Material Receipt</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Material Receipt …</a></p>', 118),
  ('de_DE', 5, '<p><b>Before you start.</b> These must exist first: <b>Business Partner</b>, Partner Location (<b>Business Partner</b>).</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Material Receipt …</a></p>', 118),
  ('de_DE', 6, '<p><b>Do it.</b> Fill <b>Material Receipt</b>, then <b>Receipt Line</b>; then the Document Action <b>Complete</b>.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Material Receipt …</a></p>', 118),
  ('de_DE', 7, '<p><b>What Complete does.</b></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Material Receipt …</a></p>', 118),
  ('de_DE', 8, '<ul><li>Ship/Receipt Confirmation: Yes: creates a ship/receipt confirmation (after the pick/QA one when both are on)</li><li>Stays In Progress while a non-customer confirmation is unprocessed</li><li>Movement Type Customer Shipment, Vendor Returns: takes the line quantity out of the locator''s on-hand stock (stocked products)</li><li>Movement Type Customer Returns, Vendor Receipts: adds the line quantity to the locator''s on-hand stock (stocked products)</li><li>Reduces the product''s ordered stock for the order line''s warehouse</li><li>Creates an invoice-receipt match when the receipt line has an invoice line</li><li>Creates a PO match linking the receipt line to its order line ✓</li><li>Offers Close as the next document action</li></ul>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Material Receipt …</a></p>', 118),
  ('de_DE', 9, '<p><b>When it refuses</b>, legacy says: “Either Order or RMA can be process on this document.”; “Period Closed”; “Back-Date transaction not allowed”; “No Document Lines found”; “Attribute Set Mandatory (Line No #… , Product=… )”; “Open: Ship/Receipt Confirmation”; “Insufficient Stock Coverage. A shipment should not be allowed if there is insufficient stock before the shipment’s movement date.”; “More than line qty on attribute tab for line …”; “Cannot correct Inventory OnHand (MA) [… ] - …”; “Could not create Material Transaction (MA) [… ]”; and 8 more in MInOut.java.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Material Receipt …</a></p>', 118),
  ('de_DE', 10, '<p><i>Read from iDempiere''s MInOut.java and the dictionary. ✓ = seen in a legacy run of 2026-11-23.</i></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Material Receipt …</a></p>', 0))
INSERT INTO AD_CtxHelpMsg (AD_CtxHelpMsg_ID, AD_CtxHelpMsg_UU, AD_CtxHelp_ID, AD_Client_ID, AD_Org_ID, Created, CreatedBy, Updated, UpdatedBy, IsActive, MsgText)
SELECT COALESCE((SELECT AD_CtxHelpMsg_ID FROM AD_CtxHelpMsg WHERE AD_CtxHelpMsg_UU='c04e9747-db51-55b6-adfb-b40c8ff9d3fb'), nextidfunc((SELECT AD_Sequence_ID FROM AD_Sequence WHERE Name='AD_CtxHelpMsg' AND IsTableID='Y')::integer, 'N')), 'c04e9747-db51-55b6-adfb-b40c8ff9d3fb', toRecordId('AD_CtxHelp', '6c52a0ab-f6bd-5348-8bd5-92cbe3fa97b1'), 0, 0, now(), 100, now(), 100, 'Y', (SELECT x.dict || COALESCE(string_agg(b.html, '' ORDER BY b.k) FILTER (WHERE b.k <= x.j), '') || COALESCE(max(b.more) FILTER (WHERE b.k = x.j + 1), '') FROM (SELECT y.dict, y.l, COALESCE((SELECT min(c.k) FROM (SELECT k, sum(length(html)) OVER (ORDER BY k) AS cum, nextlen FROM blk WHERE lang = y.l) c WHERE length(y.dict) + c.cum + c.nextlen > y.lim) - 1, (SELECT max(k) FROM blk WHERE lang = y.l)) AS j FROM (SELECT '<p><strong>' || r.Name || '</strong></p>' || COALESCE('<p><em>' || NULLIF(r.Description, '') || '</em></p>', '') || COALESCE('<p>' || NULLIF(r.Help, '') || '</p>', '') || '<hr>' AS dict, 'en' AS l, (SELECT c.FieldLength FROM AD_Column c JOIN AD_Table tb ON tb.AD_Table_ID=c.AD_Table_ID WHERE tb.TableName='AD_CtxHelpMsg' AND c.ColumnName='MsgText') AS lim) y) x JOIN blk b ON b.lang = x.l GROUP BY x.dict, x.j)
FROM AD_Tab r WHERE r.AD_Tab_ID=296
ON CONFLICT (AD_CtxHelpMsg_UU) DO UPDATE SET MsgText=EXCLUDED.MsgText, Updated=now() WHERE AD_CtxHelpMsg.MsgText IS DISTINCT FROM EXCLUDED.MsgText;
