  ('en', 3, '<p><b>Needed by.</b> Each of these asks for one on its header: <b>Sales Order</b>, <b>Purchase Order</b>, <b>Shipment (Customer)</b>, <b>Payment and Receipt</b>, <b>Purchase Invoice and Credit/Debit Note</b>, <b>Material Receipt</b>, <b>Sales Invoice and Credit/Debit Note</b>, <b>Bank/Cash Transfer</b>.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Business Partner Info …</a></p>', 123),
  ('en', 4, '<p><b>Do it.</b> Fill <b>Partner Selection</b>, then <b>Partner Orders</b>, <b>Partner Shipments</b>, <b>Partner Invoices</b>, <b>Partner Payments</b>, <b>Partner Assets</b>, <b>Partner Requests</b>.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Business Partner Info …</a></p>', 123),
  ('en', 5, '<p><i>Read from the dictionary.</i></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Business Partner Info …</a></p>', 0))
