  ('en', 1, '<p><strong>GL Journal Batch</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">GL Journal Batch …</a></p>', 118),
  ('en', 2, '<p><b>Before you start.</b> These must exist first: <b>Document Type</b>.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">GL Journal Batch …</a></p>', 118),
  ('en', 3, '<p><b>Do it.</b> Fill <b>Batch</b>, then <b>Journal</b>; then the Document Action <b>Complete</b>.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">GL Journal Batch …</a></p>', 118),
  ('en', 4, '<p><b>What Complete does.</b></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">GL Journal Batch …</a></p>', 118),
  ('en', 5, '<ul><li>Completes each active journal that is not Closed, Voided, Reversed or Completed</li><li>Stops and returns the journal status when a journal did not reach Completed</li><li>Journal Active: No: sets inactive journals processed, status Voided, action None</li><li>Overwrite Date on Complete: Yes: sets document date to today</li><li>Overwrite Sequence on Complete: Yes: assigns a new document number from the sequence</li><li>Offers Close as the next Document Action</li></ul>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">GL Journal Batch …</a></p>', 118),
  ('en', 6, '<p><b>When it refuses</b>, legacy says: “Period Closed”; “No Document Lines found”; “Control Amount differs from Balance”.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">GL Journal Batch …</a></p>', 118),
  ('en', 7, '<p><i>Read from iDempiere''s MJournalBatch.java and the dictionary. ✓ = seen in a legacy run of 2026-11-23.</i></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">GL Journal Batch …</a></p>', 0))
