-- tab 200007 Journal: DV200005 + UG7 (twin help 1000110)
INSERT INTO AD_CtxHelp (AD_CtxHelp_ID, AD_CtxHelp_UU, AD_Client_ID, AD_Org_ID, Created, CreatedBy, Updated, UpdatedBy, IsActive, CtxType, Name, Description)
SELECT COALESCE((SELECT AD_CtxHelp_ID FROM AD_CtxHelp WHERE AD_CtxHelp_UU='7b1ff739-18bc-5fa8-81a5-0e46eb8222c2'), nextidfunc((SELECT AD_Sequence_ID FROM AD_Sequence WHERE Name='AD_CtxHelp' AND IsTableID='Y')::integer, 'N')), '7b1ff739-18bc-5fa8-81a5-0e46eb8222c2', 0, 0, now(), 100, now(), 100, 'Y', 'T', 'GL Journal + 7 · Final accounts', 'https://red1oon.github.io/BIMCompiler/ERPUserGuide/#7-final-accounts'
ON CONFLICT (AD_CtxHelp_UU) DO UPDATE SET Name=EXCLUDED.Name, Description=EXCLUDED.Description, Updated=now() WHERE (AD_CtxHelp.Name, AD_CtxHelp.Description) IS DISTINCT FROM (EXCLUDED.Name, EXCLUDED.Description);
WITH blk(lang, k, html, more, nextlen) AS (VALUES
  ('en', 1, '<p><strong>GL Journal</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">GL Journal …</a></p>', 112),
  ('en', 2, '<p><b>Before you start.</b> These must exist first: <b>Currency Type</b>.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">GL Journal …</a></p>', 112),
  ('en', 3, '<p><b>Do it.</b> Fill <b>Journal</b>, then <b>Line</b>; then the Document Action <b>Complete</b>.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">GL Journal …</a></p>', 112),
  ('en', 4, '<p><b>What Complete does.</b></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">GL Journal …</a></p>', 112),
  ('en', 5, '<ul><li>Overwrite Date on Complete: Yes: sets document date to today, only when not yet processed</li><li>Overwrite Sequence on Complete: Yes: assigns a new document number from the sequence, only when not yet processed</li><li>Offers Close as the next Document Action</li></ul>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">GL Journal …</a></p>', 112),
  ('en', 6, '<p><b>When it refuses</b>, legacy says: “No Document Lines found”; “In active account - Line No=… - …”; “Account used is Document Controlled - Do not use for manual Journals. - Line No=… - …”; “Account does not have Post Actual attribute - Line No=… - …”; “Account does not have Post Budget attribute - Line No=… - …”; “Account does not have Post Statistical attribute - Line No=… - …”; “Control Amount differs from Balance”; “Unbalanced Journal and Suspense Balancing not enabled”.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">GL Journal …</a></p>', 112),
  ('en', 7, '<p><i>Read from iDempiere''s MJournal.java and the dictionary. ✓ = seen in a legacy run of 2026-11-23.</i></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">GL Journal …</a></p>', 126),
  ('en', 8, '<p><strong>7 · Final accounts</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#7-final-accounts" target="_blank">7 · Final accounts …</a></p>', 126),
  ('en', 9, '<p>Two more postings close the period: a <b><b>GL Journal</b></b> for anything that isn''t a document (a manual accrual, an inter-org transfer) and a <b><b>Bank Statement</b></b> reconciling the bank''s own records against what the ledger expects. Once every document for the period is posted, the period''s <code>fact_acct</code> <b>is</b> the ledger — there is no separate "close" step that recomputes anything; Trial Balance is a live fold of the same rows, and it balances to the cent.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#7-final-accounts" target="_blank">7 · Final accounts …</a></p>', 0),
  ('de_DE', 1, '<p><strong>7 · Abschluss</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#7-final-accounts" target="_blank">7 · Abschluss …</a></p>', 121),
  ('de_DE', 2, '<p>Zwei weitere Buchungen schließen die Periode: ein <b><b>Journal</b></b> für alles, was kein Beleg ist (eine manuelle Abgrenzung, eine Übertragung zwischen Organisationen), und ein <b><b>Bankauszug</b></b>, der die Aufzeichnungen der Bank mit dem abgleicht, was das Hauptbuch erwartet. Sobald jeder Beleg der Periode gebucht ist, <b>ist</b> <code>fact_acct</code> der Periode das Hauptbuch — es gibt keinen eigenen Abschlussschritt, der etwas neu berechnet; die Rohbilanz ist eine laufende Auswertung derselben Zeilen und geht auf den Cent auf.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#7-final-accounts" target="_blank">7 · Abschluss …</a></p>', 112),
  ('de_DE', 3, '<p><strong>GL Journal</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">GL Journal …</a></p>', 112),
  ('de_DE', 4, '<p><b>Before you start.</b> These must exist first: <b>Currency Type</b>.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">GL Journal …</a></p>', 112),
  ('de_DE', 5, '<p><b>Do it.</b> Fill <b>Journal</b>, then <b>Line</b>; then the Document Action <b>Complete</b>.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">GL Journal …</a></p>', 112),
  ('de_DE', 6, '<p><b>What Complete does.</b></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">GL Journal …</a></p>', 112),
  ('de_DE', 7, '<ul><li>Overwrite Date on Complete: Yes: sets document date to today, only when not yet processed</li><li>Overwrite Sequence on Complete: Yes: assigns a new document number from the sequence, only when not yet processed</li><li>Offers Close as the next Document Action</li></ul>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">GL Journal …</a></p>', 112),
  ('de_DE', 8, '<p><b>When it refuses</b>, legacy says: “No Document Lines found”; “In active account - Line No=… - …”; “Account used is Document Controlled - Do not use for manual Journals. - Line No=… - …”; “Account does not have Post Actual attribute - Line No=… - …”; “Account does not have Post Budget attribute - Line No=… - …”; “Account does not have Post Statistical attribute - Line No=… - …”; “Control Amount differs from Balance”; “Unbalanced Journal and Suspense Balancing not enabled”.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">GL Journal …</a></p>', 112),
  ('de_DE', 9, '<p><i>Read from iDempiere''s MJournal.java and the dictionary. ✓ = seen in a legacy run of 2026-11-23.</i></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">GL Journal …</a></p>', 0))
INSERT INTO AD_CtxHelpMsg (AD_CtxHelpMsg_ID, AD_CtxHelpMsg_UU, AD_CtxHelp_ID, AD_Client_ID, AD_Org_ID, Created, CreatedBy, Updated, UpdatedBy, IsActive, MsgText)
SELECT COALESCE((SELECT AD_CtxHelpMsg_ID FROM AD_CtxHelpMsg WHERE AD_CtxHelpMsg_UU='6754eff5-dfd2-501e-bcce-9825e79de1e2'), nextidfunc((SELECT AD_Sequence_ID FROM AD_Sequence WHERE Name='AD_CtxHelpMsg' AND IsTableID='Y')::integer, 'N')), '6754eff5-dfd2-501e-bcce-9825e79de1e2', toRecordId('AD_CtxHelp', '7b1ff739-18bc-5fa8-81a5-0e46eb8222c2'), 0, 0, now(), 100, now(), 100, 'Y', (SELECT x.dict || COALESCE(string_agg(b.html, '' ORDER BY b.k) FILTER (WHERE b.k <= x.j), '') || COALESCE(max(b.more) FILTER (WHERE b.k = x.j + 1), '') FROM (SELECT y.dict, y.l, COALESCE((SELECT min(c.k) FROM (SELECT k, sum(length(html)) OVER (ORDER BY k) AS cum, nextlen FROM blk WHERE lang = y.l) c WHERE length(y.dict) + c.cum + c.nextlen > y.lim) - 1, (SELECT max(k) FROM blk WHERE lang = y.l)) AS j FROM (SELECT '<p><strong>' || r.Name || '</strong></p>' || COALESCE('<p><em>' || NULLIF(r.Description, '') || '</em></p>', '') || COALESCE('<p>' || NULLIF(r.Help, '') || '</p>', '') || '<hr>' AS dict, 'en' AS l, (SELECT c.FieldLength FROM AD_Column c JOIN AD_Table tb ON tb.AD_Table_ID=c.AD_Table_ID WHERE tb.TableName='AD_CtxHelpMsg' AND c.ColumnName='MsgText') AS lim) y) x JOIN blk b ON b.lang = x.l GROUP BY x.dict, x.j)
