  ('en', 1, '<p><strong>Ship/Receipt Confirm</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Ship/Receipt Confirm …</a></p>', 122),
  ('en', 2, '<p><b>Do it.</b> Fill <b>Confirmation</b>, then <b>Line</b>; then the Document Action <b>Complete</b>.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Ship/Receipt Confirm …</a></p>', 122),
