  ('en', 4, '<ul><li>Flags the confirmation in dispute when any line is not fully confirmed</li><li>Split when Difference: Yes: in dispute, splits the differing quantities into a new shipment/receipt document</li><li>Offers Close as the next document action</li></ul>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Ship/Receipt Confirm …</a></p>', 122),
