  ('en', 5, '<ul><li>Creates and completes the outgoing payment on the from bank account</li><li>Creates and completes the incoming payment on the to bank account</li><li>Offers Close as the next document action</li></ul>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Bank/Cash Transfer …</a></p>', 120),
